window.POEM_DB=window.POEM_DB||{};POEM_DB["song_072"]={"n":"葛胜仲","dyn":"宋","poems":[{"t":"跋黄鲁直画","f":"七言绝句","c":["江南黄䳺飞满野，徐熙画此何为者。","百年幅纸无所直，公每玩之常在把。"]},{"t":"次韵刘无言山中五绝句敢请诸僚和之 其三","f":"七言绝句","c":["萧閒谷饮更岩栖，应笑痴人簿领迷。","万顷青油行省舫，嫩黄轻拂柳条低。"]},{"t":"次韵刘无言山中五绝句敢请诸僚和之 其五","f":"七言绝句","c":["荣槁如环浪自循，一筇双屐伴行春。","溪翁野老来争席，不识蓬山第一人。"]},{"t":"次韵刘无言山中五绝句敢请诸僚和之 其四","f":"七言绝句","c":["川原红绿远交加，春物关心梦到家。","体骨素轻惟燕子，面皮最好是桃花。"]},{"t":"次韵刘无言山中五绝句敢请诸僚和之 其二","f":"七言绝句","c":["命友登山共寄情，亦逢佳处便班荆。","有时便取琴双琐，写出苍髯夜半声。"]},{"t":"次韵刘无言山中五绝句敢请诸僚和之 其一","f":"七言绝句","c":["载酒陶春久不归，将花判断定忘疲。","寻芳便作而今计，莫待他年子满枝。"]},{"t":"木兰花/玉楼春 与诸人泛溪作","f":"七言律诗","c":["木阑干外池光阔。","午夜乔林迷岸樾。","掠船凉吹起青蘋，萦水歌声欺白雪。","檀郎响趁红牙节。","胡语嘈嘈仍切切。","人生何乐似同襟，莫待骊驹声惨咽。"]},{"t":"木兰花/玉楼春 十二月二十日卢姊生辰","f":"七言律诗","c":["谈围曾蔽青绫帐。","林下中年敦素尚。","烟波偶趁一帆风，却锁云扃来就养。","自从悟得空无相。","身把虚空来作样。","大千沙界抹为尘，未比无生真寿量。"]},{"t":"水调歌头 其二","f":"词","c":["下濑惊船驶，挥麈恐尊空。","谁吹尺八寥亮，嚼徵更含宫。","坐爱金波潋滟，影落蒲萄涨绿，夜漏尽移铜。","回棹携红袖，一水带香浓。","坐中客，驰隽辩，语无同。","青鞋黄帽，此乐谁肯换千钟。","岩壑从来无主，风月故应长在，赏不待先容。","羽化寻烟客，家有左仙翁。"]},{"t":"水调歌头 程良器嘉量别赋一阕纪泛舟之会，往返次韵 其一","f":"词","c":["夜泛南溪月，光影冷涵空。","棹飞穿碎金电，翻动水精宫。","横管何妨三弄，重醑仍须一斗，知费几青铜。","坐久桂花落，襟袖觉香浓。","庾公阁，子猷舫，兴应同。","从来好景良夜，我辈敢情钟。","但恐仙娥川后，嫌我尘容俗状，清境不相容。","击汰同情赏，赖有紫溪翁。"]},{"t":"水调歌头 其三","f":"词","c":["胜友欣倾盖，羁宦懒书空。","爱君笔力清壮，名已在蟾宫。","萧散英姿直上，自有练裙葛帔，岂待半通铜。","长短作新语，墨纸似鸦浓。","山吐月，溪泛艇，率君同。","吾侪轰饮文字，乐不在歌钟。","今夜长风万里，且倩泓澄浩荡，一为洗尘容。","世上闲荣辱，都付塞边翁。"]},{"t":"江城子 其一 呈刘无言焘","f":"词","c":["浮家重过水晶宫。","五年中。","事何穷。","无恙山溪，鬟影落青铜。","欲向旧游寻旧事，云散彩，水流东。","苔花向我似情钟。","舞霜风。","雪濛濛。","应怪史君，颜鬓便衰翁。","赖是寻芳无素约，端不恨，绿阴重。"]},{"t":"江城子 其二 和无言雪词","f":"词","c":["飞身疑到广寒宫。","玉花中。","兴何穷。","酒贵旗亭，谁是惜青铜。","飘瞥三吴真妙绝，银万里，失西东。","草堂红蜡暖歌钟。","卷帘风。","赏空濛。","丰颊修眉，鹤氅拥仙翁。","欲作氍毹花底客，清漏永，禁城重。"]},{"t":"江神子/江城子 初至休宁冬夜作","f":"词","c":["昏昏雪意惨云容。","猎霜风。","岁将穷。","流落天涯，憔悴一衰翁。","清夜小窗围兽火，倾酒绿，借颜红。","官梅疏艳小壶中。","暗香浓。","玉玲珑。","对景忽惊，身在大江东。","上国故人谁念我，晴嶂远，暮云重。"]},{"t":"行香子 愁况无聊作","f":"词","c":["风物飕飕。","木落沧洲。","渐老人、不奈悲秋。","羁怀都在，鬓上眉头。","似休文瘦，文通恨，子山愁。","庭梧影薄，篱菊香浮。","强招寻、聊命朋俦。","穷通皆梦，今古如流。","且渊明径，子猷舫，仲宣楼。"]},{"t":"西江月 其二","f":"词","c":["山镇红桃阡陌，烟迷绿水人家。","尘容误到只惊嗟。","骨冷玉堂今夜。","莫对佳人锦瑟，休辞洞府流霞。","峰回路转乱云遮。","归去空传图画。"]},{"t":"西江月 其一 与王庭锡登燕集作","f":"词","c":["清樾已生昼寂，孤花尚表春馀。","象床筠簟燕堂虚。","初过晚凉微雨。","圭璧新来北苑，鲈鱼未减东吴。","捧觞红袖透香肤。","不浥翔龙烟缕。"]},{"t":"西江月 其一","f":"词","c":["羁宦新来作恶，穷途谁肯相从。","追攀十日水云中。","情谊知君独重。","寂寂回廊小院，冥冥细雨尖风。","凤山香雪定应空。","昨夜疏枝入梦。"]},{"t":"西江月 送卫卿弟赴定远簿","f":"词","c":["万卷旧推鸿博，一官且慰蹉跎。","升平楼下赐危科。","曾对颙昂黼坐。","燕颔从来骨贵，鸾栖尚屈才多。","今宵且共入无何。","定远功名幺么。"]},{"t":"西江月 其一 连水东楼燕集","f":"词","c":["艳曲醉歌金缕，朱门高耸铜环。","中天楼观共跻攀。","飞絮落花春晚。","低映绿阴朱户，斜拖素练沧湾。","银钩华榜五云间。","奕奕蛟龙字绾。"]},{"t":"西江月 其二 叔父庆八十会作","f":"词","c":["瑞兽香云轻袅，华堂绣幕低垂。","人生七十尚为稀。","况是钓璜新岁。","登俎青梅的皪，明阑红药芳菲。","天教眉寿过期颐。","常对风光沈醉。"]},{"t":"西江月 其一 次韵林茂南博士杞泛溪","f":"词","c":["山外半规残日，云边一缕馀霞。","满城飞雪散苕花。","万顷溪连罨画。","柳恽风流旧国，鹤龄潇洒人家。","肯嗟流落在天涯。","云水从今起价。"]},{"t":"西江月 其二 三月初六日席上代监酒和","f":"词","c":["晚路交游绿酒，平生志趣青霞。","霜风时节近黄花。","泛宅舟将鹢画。","不分两溪明月，夜深只属渔家。","今朝清赏寄情涯。","肯向萦涂索价。"]},{"t":"西江月 其二 泛舟","f":"词","c":["靺鞨斜红带柳，琉璃涨绿平桥。","人在花月见新妖。","不数江南苏小。","恨寄飞花蔌蔌，情随流水迢迢。","鲤鱼风送木兰桡。","回棹荒鸡报晓。"]},{"t":"诉衷情令 友人生日","f":"词","c":["清明寒食景暄妍。","花映碧罗天。","参差捍拨齐奏，丰颊拥芳筵。","逢诞日，揖真仙。","托炉烟。","朱颜长似，头上花枝，岁岁年年。"]},{"t":"定风波 其二","f":"词","c":["共喜新凉大火流。","一声水调听歌头。","况有修蛾兼粉领。","佳景。","谢公无不碍沧洲。","平昔短檠真大漫。","气岸。","老来都向酒杯收。","云水光中修禊事。","犹记。","转头不觉已三秋。"]},{"t":"定风波 与叶少蕴、阵经仲、彦 文燕骆驼桥，少蕴作，次韵二首 其一","f":"词","c":["千叠云山万里流。","坐中碧落与鳌头。","真意见嬉吾已领。","烟景。","不辞捧诏久汀洲。","老去一官真是漫。","溪岸。","独馀此兴未能收。","留与吴儿传胜事。","长记。","赤栏桥上揽清秋。"]},{"t":"临江仙 其二 席上和呈中散兄及吴令","f":"词","c":["宝观岧峣飞雉堞，登临恍欲升仙。","野桃官柳衬吴天。","春风寒食夜，遗恨在封绵。","闻道东溟才二里，银涛直与天连。","凭谁都卷入芳尊。","赋归欢靖节，消渴解文园。"]},{"t":"临江仙 与叶少蕴梦得上 其三 巳游法华山九曲池流杯","f":"词","c":["小样洪河分九曲，飞泉环绕粼粼。","青莲往事已成尘。","羽觞浮玉甃，宝剑捧金人。","绿绮且依流水调，蓬蓬釂鼓催巡。","玉堂词客是佳宾。","茂林修竹地，大胜永和春。"]},{"t":"临江仙","f":"词","c":["雪壁歌词题尚湿，春风又见轻红。","一枝斜插映头峰。","不辞连夜赏，银烛透纱笼。","白发欺人今老矣，尊前羞见繁秾。","清香尤嫪虎溪风。","海棠须避席，佳种谩蚕丛。"]},{"t":"临江仙 其一 上巳日游海昌王氏园，吴宰效及中散兄","f":"词","c":["倦客身同舟不系，轻帆来访儒仙。","春风元巳艳阳天。","夭桃方散锦，高柳欲飞绵。","千古海昌佳绝地，双凫暂此留连。","通宵娱客破芳尊。","兰亭修禊事，梓泽醉名园。"]},{"t":"临江仙 其一 燕诸部使者","f":"词","c":["自古吴兴称冷僻，菰城水浸粼粼。","回星难望使车尘。","如何三日饮，并有五行人。","文似枚皋加敏速，记书易若张巡。","幕中无用郤嘉宾。","他年浮枣会，莫忘两溪春。"]},{"t":"临江仙 尉姜补之托疾卧家作","f":"词","c":["郊外黄垓端可厌，归来移病香闺。","象床珍簟共委蛇。","耆婆寻草尽，天女散花迟。","小雨作寒秋意晚。","檐声与梦相宜。","冷侵罗幌酒烟微。","试评书五朵，何似画双眉。"]},{"t":"临江仙","f":"词","c":["千古乌程新酿美，玉觞风过粼粼。","歌声未办起梁尘。","九天持斧客，来作绣衣人。","夙有辞华惊乙览，传闻献颂东巡。","未应握节久宾宾。","一封驰诏旨，却醉上林春。"]},{"t":"临江仙 二月二十二日锦薰阁赏花","f":"词","c":["槛外奇葩江外种，娇春未减鞓红。","画楼晴日敛云峰。","佛香来海岸，蜀锦荐灯笼。","今夜那忧杀风景，酒花来斗妖浓。","江梅冷淡避春风。","明朝来纵赏，应醉绮罗丛。"]},{"t":"临江仙 章圃赏瑞香二首 其一","f":"词","c":["二月风光浓似酒，小楼新湿青红。","碧琉璃色映群峰。","更携金凿落，来赏锦薰笼。","调客旧留□月旦，此花清软纤秾。","未饶兰蕙转光风。","赤阑呈雅艳，翠幕护芳丛。"]},{"t":"南乡子 九日黄刚定再索席间作","f":"词","c":["秋水莹精神。","靖节先生太逼真。","谈麈生风霏玉屑，津津。","爽气泠然欲侵人。","一座尽生春。","满引琼觞已半醺。","更把黄花寿彭祖，盈盈。","数阕新声又遏云。"]},{"t":"南乡子 其二 九日","f":"词","c":["拂槛晓云鲜。","销暑楼危竦半天。","曾是携宾当荐九，开筵。","度水萦山奏管弦。","黄菊映华颠。","千骑重来已六年。","楼下东流当日水，依然。","更对周旋旧七贤。"]},{"t":"南乡子 其一 九日用玉局翁韵作呈坐上诸公","f":"词","c":["晴日乱云收。","人在蘋香柳恽洲。","溪上清风楼上醉，飕飕。","共折黄花插满头。","佳客献还酬。","不负山城九日秋。","苕碧下青供酩酊，休休。","楚客当年浪自愁。"]},{"t":"南乡子 三月望日与文中诸贤泛舟南溪作","f":"词","c":["柳岸正飞绵。","选胜斋轻漾碧涟。","笑语忘怀机事尽，鸥边。","万顷溪光上下天。","菰苇久延缘。","不觉遥峰霭暮烟。","对酒莫嫌红粉陋，婵娟。","自有孤高月妇仙。"]},{"t":"点绛唇 县斋愁坐作","f":"词","c":["秋晚寒斋，藜床香篆横轻雾。","闲愁几许。","梦逐芭蕉雨。","云外哀鸿，似替幽人语。","归不去。","乱山无数。","斜日荒城鼓。"]},{"t":"浣溪沙","f":"七言古诗","c":["通白轻红溢万枝。","浓香百和透丰肌。","丹山威凤势将飞。","玉镜台前呈国艳，沈香亭北映朝曦。","如花惟有上皇妃。"]},{"t":"浣溪沙 赏酴醾","f":"七言古诗","c":["一夜狂风尽海棠。","此花天遣殿群芳。","芝兰百濯见真香。","劝客淋浪灯底韵，恼人魂梦枕边囊。","一枝插不□□□。"]},{"t":"浣溪沙","f":"七言古诗","c":["东道殷勤玉斝飞。","华灯倾国拥珠玑。","玉奴嫌瘦玉环肥。","缥缈幸闻缑岭曲，参差犹隔夏侯衣。","放开云月出清辉。"]},{"t":"浣溪沙 其一 赏梅","f":"七言古诗","c":["东阁郎官巧写真。","西湖处士妙传神。","嫣然一笑腊前春。","斗好虽无冰骨女，相宜幸是雪髯人。","且烦疏影入清尊。"]},{"t":"浣溪沙 其一","f":"七言古诗","c":["今夜风光恋渚蘋。","欲教四角出车轮。","金钗离立座生春。","神女恍惊巫峡梦，飞琼原是阆风人。","诏封后院宠儒臣。"]},{"t":"浣溪沙 其二 小饮","f":"七言古诗","c":["盘里明珠芡实香。","尊前堆雪脍丝长。","何妨羌管奏伊凉。","翠葆重生无复日，白波不釂有如江。","壁间醉墨任淋浪。"]},{"t":"浣溪沙 赏芍药","f":"七言古诗","c":["楼子包金照眼新。","香根犹带广陵尘。","翻阶不羡掖垣春。","不分与花为近侍，难甘溱洧赠闲人。","如羞如怨独含颦。"]},{"t":"浣溪沙","f":"七言古诗","c":["溪岸沈深属泛蘋。","倾城容貌此推轮。","可怜虚度二年春。","暮暮来时骚客赋，朝朝新处后庭人。","天留花月伴羁臣。"]},{"t":"浣溪沙 其一 木芍药词","f":"七言古诗","c":["可惜随风面旋飘。","直须烧烛看娇娆。","人间花月更无妖。","浓丽独将春色殿，繁华端合众芳朝。","南床应为醉陶陶。"]},{"t":"浣溪沙","f":"七言古诗","c":["斗鸭栏边晓露沾。","华堂醉赏轴珠帘。","插花人好手纤纤。","遮护轻寒施翠幄，标题仙品露牙签。","词人遗恨独江淹。"]},{"t":"浪淘沙令 十月十九夜赏菊","f":"词","c":["我爱菊花枝。","浥露偏宜。","旋移佳种一年期。","照眼黄金三径烂，可但东篱。","秋老摘花吹。","敢恨开迟。","只愁一夜便香衰。","待插满头年大也，且泛芳卮。"]},{"t":"浪淘沙令 九月十八日与千里赏菊三首 其一","f":"词","c":["又见菊花新。","色浅香匀。","老人衰病卧漳滨。","虽是无聊仍止酒，幸有嘉宾。","不用怨萧辰。","不似芳春。","请看金蕊照金尊。","今夜花前须醉倒，直到黎明。"]},{"t":"浪淘沙令 其二","f":"词","c":["歌阕斗清新。","檀板初匀。","画堂新筑太湖滨。","好是黄花开应候，聊宴亲宾。","上客即逢辰。","况是青春。","上林开宴锡尧尊。","今夜素娥真解事，偏向人明。"]},{"t":"浪淘沙令 其三","f":"词","c":["娱老小亭新。","丹垩初匀。","万枝金菊绕溪滨。","折向华堂遮醉眼，聊用娱宾。","红烛夜香辰。","广坐生春。","月波新酿入芳尊。","好向花前拚烂醉，不负承明。"]},{"t":"浪淘沙令 将去南阳作","f":"词","c":["步屧对东风。","细探春工。","百花堂下牡丹丛。","莫恨使君来便去，不见鞓红。","雾眼一衰翁。","无意芳秾。","年来结习已成空。","寄语国香雕槛里，好为人容。"]},{"t":"减字木兰花 其二 病起不见杏花作","f":"词","c":["杏花零乱。","拟把百觚来判断。","病卧漳滨。","不见枝头闹小春。","吾衰老矣。","一醉花前犹不遂。","情绪厌厌。","虚度韶光又一年。"]},{"t":"减字木兰花 其一 公弼侄初授官，以此劝酒","f":"词","c":["辛勤场屋。","未遇知音甘陆陆。","诏录遗忠。","一札天书下九重。","鹅城初命。","此去青云应渐近。","解褐恩新。","今岁吾家第四人。"]},{"t":"减字木兰花 薛肇明同二侍姬至葛山观梅，薛公会作","f":"词","c":["葛山仙隐。","尚有馀膏留旧鼎。","十里梅花。","夹道争看衮绣华。","人间妙丽。","并侍黄扉开国贵。","僻壤孤芳。","羞涩尊前不敢香。"]},{"t":"渔家傲 其一 初创真意亭于南溪，游陟晚归作","f":"词","c":["岩壑萦回云水窟。","林深路断迷烟客。","茅屋数椽携杖舄。","人寂寂。","侵檐万个琅玕碧。","倦客羁怀清似涤。","更无一点飞埃迹。","溪涨慢流过几席。","寒湜湜。","凫鹥点破琉璃色。"]},{"t":"渔家傲 其二","f":"词","c":["叠叠云山供四顾。","簿书忙里偷闲去。","心远地偏陶令趣。","登览处。","清幽疑是斜川路。","野蔌溪毛供饮具。","此身甘被烟霞痼。","兴尽碧云催日暮。","招晚渡。","遥遥一叶随鸥鹭。"]},{"t":"满庭霜/满庭芳 任昉尝为西安太守，风流名迹，图经史牒具载，感今怀古作","f":"词","c":["百不为多，一不为少，阿谁昔仕吾邦。","共推任笔，洪鼎力能扛。","不为桃花禄米，雠书倦、一苇横江。","招寻处，徒行曳杖，曾不拥麾幢。","山川，真大好，鱼矶无恙，密岭难双。","听讼诉多就，樵坞僧窗。","岁月音容远矣，风流在、遐想心降。","云烟路，搜奇吊古，时为酹空缸。"]},{"t":"瑞鹧鸪 和通判送别","f":"七言律诗","c":["两年人住岂无情。","别乘辞华四水清。","何事千钟勤饮饯，故知一别未能轻。","解龟虽幸樊笼出，挂席还愁海汐平。","江草江花都是泪，骊驹休作断肠声。"]},{"t":"瑞鹧鸪 工部七月一日生辰","f":"七言律诗","c":["火云欲避金风至。","秀气充闾初降瑞。","去家丁令却归来，还燕悬弧当日地。","金章紫绶身荣贵。","寿福天储昌又炽。","怪来一岁四迁官，还过当生元太岁。"]},{"t":"蓦山溪 送李彦时","f":"词","c":["出门西笑。","千里长安道。","不用引离声，便登荣、十洲三岛。","画船珠箔，苹末水风凉，随柳岸，楚台人，景与人俱好。","应嗟见晚，玉殿生清晓。","正是妙年时，步承明、谋身须早。","轺车肤使，新逐凯歌回，恩绋重，彩衣轻，嘉庆知多少。"]},{"t":"蓦山溪 其二","f":"词","c":["春风野外。","卵色天如水。","鱼戏舞绡纹，似出听、新声北里。","追风骏足，千骑卷高冈，一箭过，万人呼，雁落寒空里。","天穿过了，此日名穿地。","横石俯清波。","竞追随、新年乐事。","谁怜老子，使得暂遨游，争捧手，乍凭肩，夹道游人醉。"]},{"t":"蓦山溪 天穿节 和朱刑掾二首 其一","f":"词","c":["望云门外。","油壁如流水。","空巷逐朱幡，步春风、香河七里。","冶容炫服，摸石道宜男，穿翠霭，度飞桥，影在清漪里。","秦头楚尾。","千古风流地。","试问汉江边，有解佩、行云旧事。","主人是客，一笑强颁春，烧灯后，赏花前，遥忆年年醉。"]},{"t":"虞美人 题灵山广禅院","f":"词","c":["灵山法会何曾散。","此地神光满。","丁公潭下百雷霆。","疑是银河挽下、一齐倾。","高桥飞观连云起。","槛外惊湍水。","大矶才过小矶来。","应有天孙灵驭、月中回。"]},{"t":"虞美人 其二","f":"词","c":["一轮丹桂窅窊树。","光景疑非暮。","天公著意在兹时。","扫尽微云点缀、展清池。","樽前金奏无晨露。","只有君房语。","骊驹客莫赋归诗。","东道留连应赋、不庸归。"]},{"t":"虞美人 自兰陵归，冬夜饮严州酒作","f":"词","c":["严陵滩畔香醪好。","遮莫东方晓。","春风盎盎入寒肌。","人道霜浓腊月、我还疑。","红炉火热香围坐。","梅蕊迎春破。","一声清唱解人颐。","人道牢愁千斛、我谁知。"]},{"t":"虞美人 其一 酬卫卿弟兄赠","f":"词","c":["三年曾不窥园树。","辛苦萤窗暮。","怪来文誉满清时。","柿叶书残犹自、日临池。","春秋新学卑繁露。","黄卷聊堪语。","家人不用寄龟诗。","行看升平楼外、化龙归。"]},{"t":"鹊桥仙 七夕","f":"词","c":["鹊桥仙偶，天津轻渡，却笑嫦娥孤皎。","平时五夜似经年，问何事、今宵便晓。","云车将驾，神夫留恋，更吐心期多少。","支机休浪与闲人，莫倚赖、芳心素巧。"]},{"t":"鹊桥仙 七夕","f":"词","c":["凉飙破暑，清歌萦坐，缺月稀星庭户。","瓜华草草具杯盘，喜共浥、初筵零露。","天孙东处，牵牛西望，劝汝一杯清醑。","精灵何必待秋通，为一洗、朦胧今古。"]},{"t":"蝶恋花 其四","f":"词","c":["已过春分春欲去。","千炬花间，作意留春住。","一曲清歌无误顾。","绕梁馀韵归何处。","尽日劝春春不语。","红气蒸霞，且看桃千树。","才子霏谈更五鼓。","剩看走笔挥风雨。"]},{"t":"蝶恋花 章道祖倧生日","f":"词","c":["安石榴花浓绿映。","解愠风轻，乍改朱明令。","衮绣元臣门户盛。","童孙此日悬弧庆。","夜宴华堂添酒兴。","□□除书，远带天香剩。","欲浥苕波供续命。","不须龙护江心镜。"]},{"t":"蝶恋花 其三 再次韵千里照花","f":"词","c":["百紫千红今烂熳。","举烛辉花，莫厌烧令短。","酒里逢花须细看。","人生谁似英雄半。","安得红颜为老伴。","妙舞花前，杨柳夸身段。","已倒玉山回竹院。","清香不断风吹面。"]},{"t":"蝶恋花 和王廉访","f":"词","c":["风过涟漪纹縠细。","十指香檀，惊破交禽睡。","野蔌溪毛真易致。","风流未减兰亭会。","击汰千艘供洛禊。","映水垂杨，万缕拖浓翠。","小海一声波上戏。","殷勤留客千金意。"]},{"t":"蝶恋花 二月十三日同安人生日作二首 其一","f":"词","c":["雨后春光浓似醉。","著柳催花，节物侵龙忌。","绣褓香闺当日佩。","紫兰宫堕人间世。","歌管停云香吐穗。","碧酒红裳，共祝鱼轩贵。","天上阿环金箓秘。","龟龄鹤寿三千岁。"]},{"t":"蝶恋花","f":"词","c":["只恐夜深花睡去。","火照红妆，满意留宾住。","凤烛千枝花四顾。","消愁更待寻何处。","汉苑红光非浪语。","栖静亭前，都是珊瑚树。","便请催尊鸣釂鼓。","明朝风恶飘红雨。"]},{"t":"蝶恋花","f":"词","c":["共乐堂深帘不卷。","恻恻寒轻，二月春犹浅。","续寿竞来歌舞院。","龙涎香衬鲛绡段。","画栋朝飞双语燕。","端似知人，著意窥金盏。","柳外花前同祝愿。","朱颜长在年龄远。"]},{"t":"蝶恋花 其一 次韵张千里驹照花","f":"词","c":["二月春游须烂漫。","秉烛看花，只为晨曦短。","高举蜡薪通夕看。","红光万丈腾天半。","寄语平时游冶伴。","不负分阴，胜事输今段。","灯火休催归小院。","殷勤更照桃花面。"]},{"t":"醉花阴 次韵印师","f":"词","c":["东皇已有来归耗。","十里青山道。","冻蘖万株梅，一夜妆成，似趁鸣鸡早。","年时清赏曾同到。","先仗游蜂报。","抖擞旧心情，一笑酬春，不羡和羹诏。"]},{"t":"醉蓬莱 天宁节作","f":"词","c":["望葱葱佳气，虹渚祥开，斗枢光绕。","析木天津，正灵晖腾照。","鹭缀分班，象胥交贡，奉御觞清晓。","玉殿寒轻，金徒漏永，瑞炉烟袅。","万宇均欢，示慈颁燕，寿祝南山，庆均凫藻。","缥缈红云，望九重天表。","舞兽锵洋，抃鳌欣戴，度管弦声杳。","历草长新，蟠桃永秀，与天难老。"]},{"t":"鹧鸪天 新春","f":"词","c":["玉琯还飞换岁灰。","定山新棹酒船回。","年时梁燕双双在，肯为人愁便不来。","衰意绪，病情怀。","玉山今夜为谁颓。","年时梅蕊垂垂破，肯为人愁便不开。"]},{"t":"鹧鸪天","f":"词","c":["婆律香深气味佳。","玻璃仙碗进流霞。","凝膏清涤高阳醉，灵液甘和正焙芽。","香染指，浪浮花。","加笾礼尽客还家。","贯珠声断红裳散，踏影人归素月斜。"]},{"t":"鹧鸪天 赏菊二首 其一","f":"词","c":["黄菊鲜鲜带露浓。","小园开遍度香风。","自篘玉酝酬秋色，旋洗霜须对晚丛。","香在手，莫匆匆。","寻芳今夜有人同。","黄金委地新收得，莫道山翁到底穷。"]},{"t":"鹧鸪天 其一 九月十三日携家游夏氏林亭燕集作，并送汤词","f":"词","c":["小榭幽园翠箔垂。","云轻日薄淡秋晖。","菊英露浥渊明径，藕叶风吹叔宝池。","酬素景，泥芳卮。","老人痴钝强伸眉。","欢华莫遣笙歌散，归路从教灯影稀。"]},{"t":"鹧鸪天","f":"词","c":["采采黄花鹄彩浓。","吹开一夜为霜风。","已邀骚客陶元亮，不用歌姬盛小丛。","秋易老，莫匆匆。","齐山高兴古今同。","欲知此地花多少，一眼金英望不穷。"]},{"t":"嘲茶山","f":"词","c":["吴兴紫笋，实产顾渚。","唐昔底贡，阚山芽吐。","隼旟出临，虎岩亲驻。","邻邦刺史，金匏相遇。","木瓜堂前，穿云浥露。","烹蒸包发，及春未暮。","天子称珍，分甘当路。","今则不然，名毁势去。","金沙弗湘，玉食弗御。","敷荣穷山，牢落谁顾。","如女失宠，空闺自嫭。","请以千金，买长门赋。"]},{"t":"茶山解嘲","f":"词","c":["众万之生，于世暂寓。","一偾一兴，孰知其故。","退黜奚戚，进升奚慕。","岂以通塞，顾改常度。","有如我翁，昔尝掀翥。","戴纚垂缨，去天尺五。","今屏山城，亦皆时数。","左右佩剑，畴可笑侮。","翁具退省，前言大误。","用与不用，智力何预。","幸同此邦，邂逅承晤。","结为金兰，安此贫素。"]},{"t":"阅讼诉忽疲起卧少顷复视事","f":"五言古诗","c":["平明坐早衙，投缿来相踵。","讼牍鼠雀暗，吏行凫鹜拥。","外台竦风棱，檄至亟须捧。","以身为形役，劾去顾未勇。","病骨瘦栾栾，衰发希种种。"]},{"t":"送邓宁民罢瑕丘簿","f":"五言古诗","c":["火云烧晴空，大暑金石流。","行人口生烟，千里无停辀。","胡为趣遵路，僚好挽莫留。","自言为升斗，往日辞亲游。","儿嬉膝前欢，三载不可求。","所得较所失，轻重真不侔。","于兹满秩归，子职冀稍修。","微官亦何乐，触事有庶尤。","米盐聒双耳，簿领昏两眸。","畏首复畏尾，人役不得休。","岂无读书暇，顷刻但少偷。","幸此案上历，数日获到头。","白云已在眼，喜色津津浮。","我亦厌羁官，如苦南冠囚。","羡子有行色，去若登昆丘。","更书纵未下，投劾行当谋。"]},{"t":"次韵良器真意亭探韵","f":"五言古诗","c":["我爱陶渊明，脱颖深天机。","丛菊绕荒径，五柳摇幽扉。","生逢卯金兴，典午势已非。","著书但甲子，岁晚频歔欷。","仕宦聊复尔，樽酒真焉依。","南亩犹种秫，西山同采薇。","浩歌归去来，熹微恨晨晖。","迷途往莫谏，今是庶可几。","蓄琴但取意，不施弦与徽。","观其四八目，贤哲在所希。","出处固有意，夫岂轻行违。","谁云惮束带，辞荣俄拂衣。","念彼同产人，抚视因遄归。","平生共志趣，但有一翟妃。","少陵罪责子，颇谓达道非。","右丞鄙乞食，更以人我讥。","乃知第一流，尚此知音稀。","妙诗发天奥，流转同衡玑。","自谓处人境，喧无车马騑。","心与尘事远，地偏堪遁肥。","东篱秋色晚，悠然望翠微。","真意不可辨，佳气随鸟飞。","诗辞向千载，凛凛犹光辉。","我生但睎骥，望之有等威。","行怀斜川游，坐想栗里矶。","九原不可作，筑亭傍崔嵬。","独取诗句名，櫩宇殊飞翚。","岩谷有杳霭，花卉无纷菲。","修篁寒逼人，坐如霜雪飞。","诸公赏清致，野服驰鞯鞿。","经丘复寻壑，不惮历崄崎。","壶觞更命釂，藻翰各一挥。","高谈破滞论，妙处端解围。","食冷或屡暖，哦诗宁忍饥。","褒假猥见及，责善非所祈。","愿以靖节语，佩之如弦韦。"]},{"t":"送宁守罢任赴阙四首 其一","f":"五言古诗","c":["材大多不容，论刚苦难受。","儒玄阅三朝，伟冯今白首。","胸中有藏室，设张动掣肘。","人言专城乐，聊结新安绶。","独喜众毁言，不及河东守。","三年四宝堂，红梅倾白酒。","出处固有在，儿辈浪奔走。","岂复恨典签，得州大如斗。"]},{"t":"送宁守罢任赴阙四首 其二","f":"五言古诗","c":["老人聚扶杖，儿啼使君前。","习知使君清，一觞代一钱。","六城十万户，焉依刺史天。","刑清艾作韠，俗朴蒲为鞭。","赭衣入佗郡，关户得晏眠。","州乡大作社，击壤歌康年。","左轓忽照路，更借知无缘。","愿公治者广，此惠周幅员。"]},{"t":"送宁守罢任赴阙四首 其三","f":"五言古诗","c":["阳城拙催科，贾谊困迁谪。","骑曹呼马曹，罚满何止百。","一笑为阔略，坐免投此帻。","铃斋父党尊，均礼不赐隔。","人疑典午公，岂尝有此客。","连年三露章，慰荐飞络绎。","自惭骨相屯，顾使议见格。","途穷窘论报，纸札谩摇擘。"]},{"t":"送宁守罢任赴阙四首 其四","f":"五言古诗","c":["紫阳如佳人，晻霭送征舳。","含愁入长眉，尽敛故时绿。","语儿已在眼，欢迎走僮仆。","旧社问枌榆，新径开松菊。","还家聊作客，行色催辇毂。","同升纱笼人，拔士有丰禄。","会当出水镜，一洗凡眼肉。","跻荣赤墀涂，雁门诗可复。"]},{"t":"兖学叙旧呈子充","f":"五言古诗","c":["羲和无停轮，年鬓日夜改。","惟有金兰心，岁晚依然在。","颇忆四门馆，研席同诸生。","联名理朱穆，结驷留阳城。","缟纻初定交，车裘容共敝。","骏马驰春风，休沐章台市。","年少未涉道，惟论场屋文。","鼻息拂霄汉，心期勇风云。","春闱锁儒仙，试席两心竞。","阆仙时乞灵，孤懿肯移病。","喜君先得桂，时我犹飘蓬。","凤凰黄鹄叹，振手国门东。","离群十周星，为僚一都会。","涵牛鼎烹鸡，邑小非材配。","理县不用谱，政如密与蒲。","糗水代厨传，木索閒庭除。","肯怜冰子穷，夜冻午不粒。","绨袍累故人，口腹烦安邑。","更迂长者辙，来顾空宇中。","坐令羁官兴，不复叹秋风。"]},{"t":"立秋日六兄将仕先入都赴铨试会饮东郊作诗送之","f":"五言古诗","c":["缺月耿疏林，凉飙拂轻衽。","荒溪趣遵涂，客子敢安枕。","自言赴铨府，试判取微廪。","清时广招延，选部杂流品。","门子萃金张，文人富曹沈。","春秋两较试，器业一精审。","探珠到渊洄，求金自沙墋。","腾装分区区，蓄志常懔懔。","家翁昔初仕，恬退声藉甚。","求閒绝外慕，行义鄙中荏。","以兹久淹蟠，通籍才十稔。","飘然宦游倦，遽以归休谂。","优恩得世禄，纶告下绨锦。","兄材济世美，圣读近天禀。","所长皆盖人，无一可镌锓。","摛辞昔贤均，说经馀子噤。","临书蛇蚓结，搊琴鱼鲔淰。","辛勤客虞庠，藜藿就烹饪。","谓当妙穿杨，百中羽皆饮。","如何遭刖频，归步每踔踸。","兹行定焚舟，已事空拾沈。","将期冠群英，喜剧不能寝。"]},{"t":"送友赴试钜野送之西门时方有外舅之戚极目无聊归不得卧作诗五首却寄以风云入壮怀为韵 其一","f":"五言古诗","c":["三吴炊未熟，祗命挈挈东。","铅刀一何补，粮食赋頖宫。","寥寥坐空庐，寂寞如扬雄。","引脰望南境，不及马牛风。","何如广文饭，终岁与子同。","年颜吾老矣，痴愚心尚童。","子虽齿发少，操行一老翁。","岂独友于厚，政赖博我功。","儒玄各精诣，衮衮倾谈丛。","欲知不常处，乃在阿堵中。"]},{"t":"送友赴试钜野送之西门时方有外舅之戚极目无聊归不得卧作诗五首却寄以风云入壮怀为韵 其二","f":"五言古诗","c":["此子早树立，抗志高浮云。","委蛇处州巷，颇以隽秀闻。","挟书从我游，追琢益自勤。","便便经与史，用志初不分。","疑篇了咄嗟，确论摧纷纭。","文辞近道要，见者笔为焚。","差肩鲁诸儒，蔼蔼扬清芬。","秋风济阳战，足扫千人军。","只今呼贺酒，伫子归策勋。"]},{"t":"送友赴试钜野送之西门时方有外舅之戚极目无聊归不得卧作诗五首却寄以风云入壮怀为韵 其三","f":"五言古诗","c":["寒斋篁竹间，墙屋久不葺。","旁穿及上漏，雨过满床湿。","忍饥哦诗书，亭午或未粒。","先生自不饱，濡沫岂能及。","出门有纷奢，囊空自羞涩。","世事不如意，八九更论十。","问君胡不归，肄业乃其急。","自言苦心志，更觉聪明入。","谁能学仲卿，夜抱牛衣泣。","说经已铿铿，青紫真可拾。"]},{"t":"送友赴试钜野送之西门时方有外舅之戚极目无聊归不得卧作诗五首却寄以风云入壮怀为韵 其四","f":"五言古诗","c":["寥寥里选空，龊龊士风丧。","狂澜欲东之，汎滥不可障。","词场自衒鬻，相与计留放。","夸毗徒一名，倾排至千状。","不知厉术业，徒欲挤辈行。","黄生独往资，风义古人抗。","悠悠衰俗中，此士真可壮。"]},{"t":"送友赴试钜野送之西门时方有外舅之戚极目无聊归不得卧作诗五首却寄以风云入壮怀为韵 其五","f":"五言古诗","c":["江南一纸书，沉忧割中怀。","嗟予足忧患，生世苦不谐。","匆匆子行色，适与远讣偕。","破涕彊出祖，尊酒不及排。","还归坐讲肄，寒筱摇空斋。","推门误相从，忽惊形影乖。","谁云阻一舍，目断真天涯。","念子早自力，清明播朋侪。","触热赴夷路，跨马脚不鞋。","自言取乡送，通显资其阶。","临别何以赠，手板裁香楷。"]},{"t":"寄题长安谭损之遐观阁","f":"五言古诗","c":["乾坤一浩荡，小智自窘拘。","低徊裈中虱，龌龊辕下驹。","达人独矫首，抗志在八区。","归来绕荒径，所喜觉迷途。","时读穆满传，乍观山海图。","林木净交荫，所见与道俱。","谁能远羁宦，五斗一丈夫。","筑阁者谁子，无乃柴桑徒。"]},{"t":"次韵张宏道劝释奠致斋","f":"五言古诗","c":["斋居屏尘务，况复儒宫清。","木落必粪本，祭菜敢不诚。","瑚簋见三代，错落罗两楹。","骨冷破梦境，虚窗坐黎明。","祠官趣盥颒，珊然环佩声。","巍巍素王像，视若四海营。","当时杏坛士，与享彯华缨。","乐教属昭代，弟子陈歌笙。","端如从陈蔡，琴舞纷纵横。","元功流万祀，德大遍诸生。"]},{"t":"次韵卢行之知原见赠","f":"五言古诗","c":["元丰诗礼将，勋略传万口。","长城国西陲，寄托十年久。","折箠笞黠羌，游魂屡穷走。","羊公缓裘带，李广静刁斗。","黑头已青云，日昃笑击缶。","阴功与忠谏，二俱宜有后。","绳绳丈夫子，茂宰最称首。","不裁犹能裁，应有既尽有。","丘坟三十车，习复不置手。","尚友千载人，岂论骨已朽。","芳兰秀深林，嘉芑就菑亩。","宜为数旬客，顾作三日妇。","行闻尺一来，内阁延枚叟。"]},{"t":"次韵季明","f":"五言古诗","c":["我生任飘荡，所向如虚舟。","谁能涉险难，入此正急流。","行止两无累，自遂逍遥游。","巉路岂不佳，夙意非所留。","迎亲四门馆，登道初麦秋。","政喜寝门近，敢言征路悠。","山阳雨连月，平陆不可求。","居将杂蛙黾，渚不辨马牛。","淮湖共瀰漫，以为行者忧。","今朝好风色，歌笑轻阳侯。","红鳞上圉圉，可以供殽羞。","便呼拍浮船，甘味苴两头。","坐待缺月挂，玉斧亦可修。","酩酊聊自彊，淹速非人谋。","数程次京国，犹待半蓐收。","相从共蒲酒，赖有嵇阮俦。"]},{"t":"再和示季明","f":"五言古诗","c":["剑不用置履，柏非可为舟。","古来倜傥士，渠肯甘凡流。","君材早迈往，华问驰交游。","高文笔如扫，隽辨舌不留。","白黑自了了，皮里藏阳秋。","拥卷得渊旨，奋辞祛缪悠。","身虽不求人，政自人所求。","恢恢有馀刃，所见无全牛。","亨衢恐不免，位遇岂足忧。","初官三语掾，审克裨藩侯。","退公丰暇裕，问学日益羞。","行为孔独诵，端以贾长头。","嗟余过立境，没没谢蕴修。","广文一饭足，其他非所谋。","胜境定时访，良书亦可收。","但恐与君别，无复往朋俦。"]},{"t":"诵金刚经满二藏偶作","f":"五言古诗","c":["我诵大智度，非疾无日空。","铜炉海岸香，亦复充净供。","积数向洛叉，而实未尝诵。","凡诸有为法，实如幻泡梦。","一字本不立，况有千百颂。","不受一切法，乃簉预流众。","于法有所得，十八成不共。","妙理端会心，筌蹄那复用。"]},{"t":"妙净院","f":"五言古诗","c":["入门无行路，十顷涨方塘。","藉叶受微雨，瑟瑟泻沧浪。","石梁一何伟，延袤百肘长。","临流两华屋，东西蔚相望。","云堂始断手，润蒸松桂香。","弛檐谐云卧，何殊赞公房。","夜步庭除月，心与空水凉。","世人侈居第，规永庇蒸尝。","墓木未及拱，破鬻何披猖。","何如施给园，千载绵宝坊。","君看寺前村，至今俞氏昌。"]},{"t":"禅静寺","f":"五言古诗","c":["古寺邻曹崇，怪石罗庭户。","奇礓漫难名，郁林不知数。","集虚竦苍桂，左纽真独步。","两诗照丹壁，好在支与许。","却坐留芳轩，松竹发佳趣。","山行未觉疲，更问劳劳路。"]},{"t":"采芝庵明辨师求泉名以月光命之","f":"五言古诗","c":["方池洌寒泉，湛湛缨可濯。","其源出阳崖，其委则阴壑。","斋盂给晨炊，茗椀共午酌。","道人习水观，趺坐閒两屩。","性水了真空，非以识心度。","浮幢诸刹海，视身同不涸。","为名月光泉，永配一宿觉。"]},{"t":"己丑次梅溪乐平寺兄子宗丞尝监镇即寺为廨卒官晚之东庄","f":"五言古诗","c":["兰陵华腴姓，数不到吾族。","何堪从子贤，变灭石火速。","早搴东堂桂，宗寺副惇睦。","迎亲官就此，半载欢水菽。","方开万里涂，一蹶遽折轴。","我时局里居，十起愧骨肉。","朅来访遗踪，徙倚寒溪曲。","人与紫梅花，二俱不可续。","忧端齐前山，东庄写松竹。"]},{"t":"次去非韵简元忠使君","f":"五言古诗","c":["翻飞堕青冥，岩邑漫濡迹。","脱无贤已交，久矣去移疾。","兴州天下士，奇节非碌碌。","魁然索价高，未肯轻沽玉。","居閒时过我，端若右尹夕。","文词天分工，沈诗更任笔。","蝉连语入微，不觉听更仆。","旧交半廊庙，勋阀藏帝箓。","毋宁一麾出，不屈数旬客。","五十始过二，荣途尚努力。","才资况加人，何止什与百。","是事姑置之，秋日方在翼。","鲜鲜黄金花，冷艳照墙屋。","郊原沐时雨，枯槁苏沾足。","城南天息河，流水有令德。","相携共击汰，泛此寒湜湜。"]},{"t":"九月二十四日陪少蕴左辖饮朱氏林亭以朱行中寄其弟诗为韵席上同赋","f":"五言古诗","c":["萧晨天宇澄，云物扫氛霿。","寒飙振飞藿，策策商声中。","官散无町畦，出若孤云纵。","仰怀山中相，隐居邻二仲。","驾言访精舍，连日食指动。","午坐烹茶龙，夜饮烧烛凤。","殷勤数啖我，省烦惭闵贡。","美哉澄空堤，松竹锁岩洞。","怪石初平留，嘉树橐驼种。","山水有清音，招隐诗可诵。","初如叩清角，乍若听幽弄。","窥临已不恶，况乃陪营从。","清谈木霏屑，圆机盘走汞。","清寒逼吟魄，不起梨云梦。","半生了官事，今假幸少空。","坐有第一流，不饮宜自讼。","人生行乐耳，急若奉漏瓮。","东山恐不免，衮职行登用。","槎通天衢升，茅茹诸贤共。","惟有数奇人，辛苦仍耘葑。"]},{"t":"蒙左辖复次韵见寄复赋一首","f":"五言古诗","c":["四海吴兴公，嗜学屏尘霿。","妙龄仪天朝，献纳言必中。","轩轩云鹏升，洋洋壑鱼纵。","内庭大手笔，傅班真伯仲。","武库富所藏，砥柱矻不动。","肮脏妨居中，大观俄归凤。","归来一丘壑，弹冠谢王贡。","嶪峨悬霤山，窈窕琦玕洞。","奇礓不待辇，桐竹已前种。","神畀贾长头，天扶孔独诵。","衡霍缩地来，林深听幽哢。","轩池揽风月，杖屦屏营从。","山赀自足了，不待烧铅汞。","斯文未应丧，审象俄入梦。","岩廊翊元化，告猷无日空。","上游倚韬钤，出听秣陵讼。","方将脍刘辟，行酒赢万瓮。","急流自勇退，惟深閟神用。","行藏亦何常，此道圣贤共。","终为岩野霖，且并苕溪葑。"]},{"t":"盆池放鱼呈曹文中","f":"五言古诗","c":["小鱼如针锋，大鱼如柳叶。","舍之石斛中，泼泼逝鳞鬣。","秋毫麸与籺，腹果意各惬。","渺如在湖海，不叹杯水狭。","笑之复自笑，邑小大邦摄。","摇足已恐堕，一动不敢辄。","廪人给五斗，饘粥周儿妾。","虽然颇自适，携杖园日涉。","岂羡蝉冕窟，迁擢等常猎。","漆园信知鱼，非惟常梦蝶。"]},{"t":"辛卯次雾山大明院进士万廷老介来谒","f":"五言古诗","c":["石桥跨斯干，路转得佛庙。","叩钟集黑衣，迎我千指闹。","龙宫五十轴，金碧烂相照。","空翠沾我襟，冥濛认堂奥。","无乃张公超，五里方术妙。","邻居一逢掖，作名屣为倒。","莫言山未深，终当隐玄豹。"]},{"t":"寄友卿窄韵一首","f":"五言古诗","c":["昔子游鲁中，飘然起幽栖。","翛翛一书簏，长物无所携。","辛勤涉长道，足趼面目黧。","自言寡闻识，走俗多沉迷。","今不勇自奋，蹉跎将噬脐。","类渴欲石髓，如矇想金篦。","来簉胄子席，求言学端倪。","嗟予浅闻道，太仓之一稊。","松菊有荒径，桃李无成蹊。","胡能使谷似，每每赪颜低。","晨昏不予舍，三岁改摄提。","对案但苜蓿，有黍多无鸡。","一笑为流啜，甘若羊新刲。","秋霜八九月，絺绤临风凄。","宁甘范叔寒，不求故人绨。","夜窗经与史，短檠照栖栖。","靡曼一不顾，端如金日磾。","嘉子甚年少，老成同齿齯。","照庭真玉树，饤座称佳梨。","为文颇挺拔，绝去翰墨畦。","声华出诸彦，籍籍喧青齐。","遂收济北荐，谓即辞蒿藜。","如何尚龃龉，时命多乖暌。","方今天子圣，隆学古与稽。","美化浃辽夏，文星动娄奎。","郡邑各黉宇，夏屋华榱题。","师儒自廷授，望实多金闺。","大烹极鼎味，岂复嗟盐齑。","月书季有考，升舍兹其梯。","吾邦矧多士，擅富浙水西。","文华灿星斗，光彩腾虹霓。","似闻与二难，同起公堂跻。","侃侃共辉映，乳酪兼酥醍。","文高各扬迈，质美皆悬黎。","生资固不凡，器用况已犀。","先生力推引，同志无倾挤。","亨涂可自致，如车资軏輗。","明年拔寒俊，一封下芝泥。","乡校伫宾贡，跋马登隋堤。","谈笑取通显，岂直组与圭。"]},{"t":"张周韩侍御迁居北市示诗次韵","f":"五言古诗","c":["神羊厌峨冠，铜虎出分土。","一区久未卜，薄遽归无所。","寓居得爽垲，众口粗安堵。","委怀荣槁外，长歌乐韶武。","自言倦霜台，笔端有萧斧。","毋宁乞小愒，松菊问衡宇。","未看武当山，聊踏南梁鼓。","浮生皆寄耳，莫作飘流苦。","要津况虚位，掀腾在仰俯。","政恐尺一来，均人隔绥抚。"]},{"t":"朱偃吹笛","f":"五言古诗","c":["李谟美梁州，独孤生窃笑。","声既杂夷乐，叠复误水调。","区区许云封，女子称商肖。","天宝小部乐，能使玉妃釂。","论竹取云梦，不老不可少。","七月望一周，生伐以此料。","韦郎衒名管，半曲裂数窍。","风流渺无继，是子差可教。","安得君山翁，渔艇巴陵道。","擪捻三五声，万籁发天妙。","清音彻四山，猿鸟惊飞噭。","大管藏合拱，直俟元君召。"]},{"t":"壬辰次灵峰山百福院","f":"五言古诗","c":["豺虎纵郁攸，此寺神独赦。","楼台倚山腹，碧瓦粲相射。","奔崖插云霄，缩地见衡华。","竹翠染僧裾，泉声喧佛舍。","峰峦佳有馀，顾揖真不暇。","我欲陟山椒，嶝崄未应怕。","摩娑旧圣石，政恐嫌俗驾。","感慨明义师，徘徊一悲咤。"]},{"t":"披云台","f":"五言古诗","c":["深公出东都，山色已清好。","流行沧江上，快意时绝倒。","洗尽眼界尘，招提迹如扫。","众挽来灵山，世故亦相恼。","平生爱山心，不厌更幽讨。","扪萝开细岑，脱履藉丰草。","聊烦坡陀石，坐此突兀老。","是身端如云，去住殊未保。","孤峰起孤烟，晴湖漾晴昊。","宾主两忘言，可为知者道。"]},{"t":"跋胡德辉诗卷","f":"五言古诗","c":["一官三语掾，驱车大河北。","饭涩羹亦稀，哦诗写胸臆。","作者非难到，已自入阃域。","邮筒远相饷，我岂今衡尺。","粗能擿陇云，亦不误雌霓。","千里得行记，了了所见历。","士材有如此，磊落固易识。","寄语直指公，勿作寒蝉默。"]},{"t":"德辉次旧韵见寄复和","f":"五言古诗","c":["邗沟别清扬，十稔限南北。","羁游多面交，从谁吐心臆。","初筵群玉府，香誉蔼区域。","如何窾言加，进寸辄退尺。","归来赋郊居，邀客赏冰霓。","青云一蹙易，斜飞要游历。","水镜岂无人，瑾瑜固易识。","君子有常道，要不失语默。"]},{"t":"题柘城怀古亭","f":"五言古诗","c":["陈本太姬封，卒以夏姬乱。","君臣同宣淫，父子并遘患。","直谏泄冶死，诈忠巫臣窜。","郢兵讨少西，昊墟且为县。","呜呼女戎祸，陈祚仅如线。","馀波及羊舌，伯石实首难。","我行径株林，怀古一兴叹。","流波似当时，惟有城东涣。"]},{"t":"癸巳次古浮山普慈寺","f":"五言古诗","c":["老人百念冷，看山独不足。","未能寻地肺，聊复访天目。","路出古浮山，木杪飞华屋。","松迷突兀殿，云锁窈窕谷。","高阁藏复道，朱栏穿屈曲。","羲和隐昆崙，借此休驺仆。","小摘园中蔬，充我属餍腹。","缅怀峨豸翁，草庐亲卜筑。","意恃金匕药，终亦戢一木。","不如学无生，妙谛祖身毒。"]},{"t":"甲午次东天目山紫阳观梁武初置昭明太子勒碑纪当时恩奖之盛","f":"五言古诗","c":["萧公老寺主，亦复知寻真。","大同筑精舍，招延羽衣宾。","园囿廓数里，严更纷徼巡。","东宫奋鸿笔，纪事传坚珉。","山基半吴境，高与帝所邻。","伟哉古石室，空洞容千人。","当年许远游，自此升玉宸。","至今雪山草，灵苗杂荆榛。","幽池湛寒水，亦说栖龙鳞。","灵物有变化，谁能穷其神。","窥临拟仙去，未信隔两尘。"]},{"t":"乙未次普信院与首座惟表谈道","f":"五言古诗","c":["蓐食起紫阳，憩寺始亭午。","清幽释子居，山影落窗户。","楼台互相临，云石粲可睹。","阴崖溜清泉，甘美过牛乳。","山僧立胜事，争以筠筒股。","表公久游方，妙谛明佛祖。","虽未众拆床，已见屦满户。","相携环翠堂，身觉度飞羽。","登临固已往，况乃真吾土。"]},{"t":"余谪沙阳地僻家远遇寒食如不知盖闽人亦不甚重其节也感而赋诗五首以杜子美无家对寒食五字为韵 其一","f":"五言古诗","c":["往岁遇寒食，亲宾相与娱。","飘零客异土，对之浑若无。","岂不念佳节，寸心愁欲枯。","花间有好鸟，劝我提胡卢。","一醉聊自适，醉梦归东吴。"]},{"t":"余谪沙阳地僻家远遇寒食如不知盖闽人亦不甚重其节也感而赋诗五首以杜子美无家对寒食五字为韵 其二","f":"五言古诗","c":["异县遇寒食，怅然怀我家。","千里遥相望，各在天一涯。","佳节无与同，冉冉悲年华。","鸣禽花底聒，舞燕风中斜。","物情各自在，羁束诚可嗟。"]},{"t":"余谪沙阳地僻家远遇寒食如不知盖闽人亦不甚重其节也感而赋诗五首以杜子美无家对寒食五字为韵 其三","f":"五言古诗","c":["天涯遇寒食，嘉节无与对。","独酌一杯酒，慷慨使心痗。","来者复可追，既往那复悔。","翛然畎亩心，敢忘犬马爱。","之推自欲隐，去去何所怼。"]},{"t":"余谪沙阳地僻家远遇寒食如不知盖闽人亦不甚重其节也感而赋诗五首以杜子美无家对寒食五字为韵 其四","f":"五言古诗","c":["嘉节遇寒食，春阴犹作寒。","闽人不知重，浑作等闲看。","饧粥不复煮，青枫谁与钻。","开窗延霁景，脩竹正团栾。","翠眉双侍女，对此一樽残。"]},{"t":"余谪沙阳地僻家远遇寒食如不知盖闽人亦不甚重其节也感而赋诗五首以杜子美无家对寒食五字为韵 其五","f":"五言古诗","c":["逐客已凄凉，矧复值寒食。","花深日迟迟，院静春寂寂。","雨馀山吐青，日落霞扫赤。","浙江渺何在，三月无消息。","弃置勿复陈，吾心乃如石。"]},{"t":"涉汝诗","f":"五言古诗","c":["居官行两周，出郭劣半里。","名称临汝守，初未涉汝水。","今朝破巨浪，万顷寄一苇。","源从天息山，此地乃其委。","青嵩正北踊，紫逻复西峙。","两岸千万峰，落影照清泚。","下濑剧迅速，舟轻如激矢。","周南滞留恨，此假聊一洗。","怅无周旋人，同载如郭李。","似闻汝阴湖，扬尘清颍尾。","醉翁漾舟处，无复碧染指。","岁月供感概，人事有迁徙。","兹水美洋洋，正堪行乐耳。"]},{"t":"再和涉汝诗呈去非伯仲","f":"五言古诗","c":["清汝如荆溪，不异我州里。","奔流相豗蹙，敢谓衣带水。","携宾泛漫汗，画鹢延缘苇。","出城散腰脚，朱墨逃纷委。","却望城中塔，烟林隐孤峙。","何人貌清景，墨笔可就泚。","幽寻要关楗，善饱未遗矢。","尘缨政堪濯，凡髓亦可洗。","不须学东山，韶颜载桃李。","顾当似白傅，玉粒炊船尾。","脍缕斫鲜鳞，遣客动食指。","风流得意事，一官不愿徙。","脱有戚戚时，晤言消之耳。"]},{"t":"送侄元延之官","f":"五言古诗","c":["浮游五岭南，屐裙遍迁客。","宠以鳌冠诗，独步文章伯。","十年未得调，浪有声华白。","来宁未死叔，知费几马策。","相携泛清汝，壶酒映山碧。","肯嗣陈留风，一笑饮为剧。","清途子初延，我老欲投劾。","出处政参辰，此欢宁易得。"]},{"t":"俞居易兄弟并时为属邑长示其父所藏东坡送行诗用其韵跋卷末","f":"五言古诗","c":["吾州两支邑，伯季俱鸣琴。","清谈一倾倒，亹亹正始音。","文室赖芝兰，药笼资桂参。","猥示晏楹书，什袭缄藏深。","好事识雅趣，扬美知孝心。","跻荣荷门基，行矣勋业寻。"]},{"t":"戊戌次福胜院","f":"五言古诗","c":["锦溪足墟落，高陆推繁华。","岂惟邑屋富，政自山水佳。","幽清背人境，千柱梵王家。","巍巍二子亭，云表飞檐牙。","我生功名忤，岩壑为生涯。","山僧类祝田，施薄求者奢。","乞书鸣刹疏，无鹅惟泼茶。","一笑为涉笔，勿笑蟠秋蛇。"]},{"t":"比作青萝山塔记并徐敏求墓铭皆蒙宏道为书作诗以谢","f":"五言古诗","c":["文苑无飞声，碑板谬见赴。","结因时佞佛，书美间谀墓。","从僚乞正书，见许不嫌屡。","虞筋与柳骨，浓纤皆合度。","浮海观鸿戏，抉石逢猊怒。","吾文敢言绝，骥尾蝇所附。","它年翰墨场，不朽知有助。"]},{"t":"次长清寺","f":"五言古诗","c":["迎宾一红亭，栋宇飞半岭。","松筠引幽步，以渐入佳境。","阴风起涧壑，凛冽噤蛙黾。","归云拥僧裓，飞溜入茶鼎。","支筇薰风阁，玉溪两峰并。","中阙认牢山，一点烟鬟整。","我来见所见，赍恨在俄顷。","丘樊绝泥滓，钟鼎值机阱。","老逐黑衣居，此心真炯炯。"]},{"t":"至南阳却寄吴兴诸僚","f":"五言古诗","c":["震州推不去，游食岁月久。","尺一从天来，换作秦头守。","迎新无竹马，记旧已刍狗。","迂愚敢护前，警发赖鞭后。","独坐百花堂，还忆百花酒。"]},{"t":"与襄阳太守张亚仲泛汉江","f":"五言古诗","c":["春波涨酦醅，绿净疑染黛。","神女昔江皋，玩珠仍解佩。","沙光射目明，浪影摇风碎。","乐哉今日游，放溜舞滂湃。","华觞挹空阔，叠鼓助击汰。","仰视白铜堤，岑楼飞綵绘。","游女凭危栏，纷若五家队。","真想谢窘拘，意有千里快。","远岸指烟蓝，飞流罗水硙。","尚想竞渡时，千船唱何在。"]},{"t":"襄阳大悲院作","f":"五言古诗","c":["善财叩补陀，大千一弹指。","我行无神足，重趼二百里。","中年逢百罹，所欠但一死。","稽首闻薰王，觊以俗障洗。","鱼山彊赞述，文污梵书庋。","自怜迷本闻，云何见大士。","觉与所觉空，根脱不用耳。","圆融声度垣，变现月映水。","臂目恒河沙，如幻本一理。","以是见观音，文殊亦如是。"]},{"t":"乾明院作","f":"五言古诗","c":["我欲乞襄阳，驱车岘山址。","文吊杜征南，酒酹羊叔子。","披榛访二碑，事辞俱俊伟。","高贤千载后，遗魄犹登此。","一官推不去，事故违愿始。","不如造乾明，山名亦相似。","交流千斛乳，未减汉江水。","遐眺真不恶，悲伤未烛理。","湮没与垂名，趋死皆一轨。","我与同游人，痛饮共择旨。","生前一杯重，恨山无石髓。","预忧名不传，却笑邹从事。"]},{"t":"游岘山","f":"五言古诗","c":["山随宇宙结，千古真苒苒。","登临足揽胜，兹来余复忝。","山椒耸太华，夷路谢跻险。","溶溶鸭头水，绿净衣可染。","渔师网槎头，尽以红鲜掩。","金刀鲙缕飞，来佐华觞滟。","前修俱鬼录，勋阀谩琬琰。","谷虚禽响答，月皎烟华敛。","同登幸旷士，形迹孰拘检。","长啸揖清流，一洗邹湛谄。"]},{"t":"次韵叶梦得游西余山","f":"五言古诗","c":["秋霖喜新霁，裹饭山中游。","遥指大夫桥，閒泛野人舟。","追随得胜客，雅趣同沧洲。","山路已清绝，颢气况蓐收。","乱石蹲狠羊，苍官耸髯虬。","古寺亦何有，森森潇洒侯。","忘怀一笑粲，更以大白浮。","翰林廊庙姿，席珍韫天球。","如何问三径，更复寻一丘。","升高涩投足，陟险眩回眸。","洞庭四万顷，旁占铛脚州。","中有东西山，千奴熟霜秋。","孤亭快写望，欲去更少休。","菟裘便可卜，何必依先畴。","徘徊共怀古，徂岁真如流。","封侯昔此地，顾余乃诸刘。","一朝失茅土，窘急须人周。","雍门曲池叹，事往将何求。","云木馀参错，烟岩自深幽。","人生行乐耳，慎勿曲如钩。"]},{"t":"柏悦堂宴集晚移望岳亭德升有诗复次韵","f":"五言古诗","c":["阴森美章园，爽垲背尘陌。","纷纷辟疆家，胜处此其伯。","登危览幽奇，宽敞荡喧窄。","层层绿阴暗，中有孤花拆。","三品玩伏虎，两部当鸣蝈。","主人延客眼，清映壶觞碧。","茂宰工拨烦，恢恢奏刀騞。","议郎兼语掾，阖府畏局蹐。","仇梅诸钜公，燕笑欢一席。","蹇予但空餐，营职无半策。","文墨彊抽身，林池同息迹。","金火争伏见，执热如焚炙。","颇愿百斛船，浮浮两头拍。","岳云插晴空，移尊及未夕。","清飙起四座，肃肃生羽翮。","人生不谋欢，带眼计月瘠。","谁能较荣槁，琐尾论干泽。","相从饮文字，一笑百忧释。","歌呼到尔汝，坐待霜月白。","归轩踏清影，光谢纱笼赫。"]},{"t":"幽居夙兴","f":"五言古诗","c":["宴安毒于鸩，嗜睡真成蛇。","揽衣待明发，是味岂不佳。","天宇自澄穆，群嚣肃无哗。","喔咿鸡一鸣，众星犹撒沙。","皂荚颒头目，杨枝清齿牙。","炉中结愿香，净几对名花。","澄怀睹道秘，浮念无由邪。","欠伸起三昧，云锦升朝霞。"]},{"t":"蒙莫伯镕饷酒携即菁村元举山庄赏菊坐客皆称叹以诗二首谢 其一","f":"五言古诗","c":["野饮政自乐，何庸拘束交。","穷居阙醇旨，逼此岁欲凋。","冷仙歘照坐，开尝惊韵高。","秋空映黄菊，气澄扫微霄。","携之寿佳客，岂讳十里劳。","供酿者谁子，颇疑人姓焦。","三杯反淳朴，一盏破郁陶。","酒材兼谱至，我醉吟今朝。"]},{"t":"蒙莫伯镕饷酒携即菁村元举山庄赏菊坐客皆称叹以诗二首谢 其二","f":"五言古诗","c":["迷涂不自觉，坐见六秩交。","霜发凛无几，况此日夜凋。","所寄在酒盏，倾银不辞高。","浇我磊块胸，那复气干霄。","手开赤泥封，不办呼孟劳。","乍纾愁肠回，亦沃渴肺焦。","君甚似江州，愧我非姓陶。","为僚且亲串，酌我非一朝。"]},{"t":"谢洛师蔡尹饷酒","f":"五言古诗","c":["叩门赤县尹，来饷青州酒。","底贡上天阍，馀沥到衰朽。","开尝正及卯，醇旨异失酉。","公不数瑶泉，家还卑玉友。","我时苦无悰，愁绪不论斗。","纷纷方寸乱，飞絮起风柳。","呼儿共一尊，盎盎纯气守。","岂惟诗胆大，更觉魔军走。","寄谢魏阳元，频望扫愁帚。"]},{"t":"和韵答马用宏朝散","f":"五言古诗","c":["三吴汗漫游，弥月沐风雨。","归来骇贫舍，忽有金刚杵。","岂惟心疾失，顿觉头风愈。","句如冰壶清，格类瓦棺古。","五言有奥境，此段得笺诂。","吾衰久寂寂，笑人忧邓禹。","自贬岂不能，趋竞虞姗侮。","洞庭岩壑秀，信美真吾土。","秋涛浮乾坤，日月互吞吐。","中有七十山，招提称踵武。","归命两足尊，一洗俗谛苦。","但喜经翻贝，那知檄驰羽。","钟鱼走诸刹，衽席讵安处。","洞天隔尘寰，仙境一二数。","毛公金丹成，拔宅已轻举。","空馀朝斗坛，遗址犹可睹。","法城有龙象，今作西山主。","净瓶逗真机，松枝代挥麈。","示我第一义，金篦破昏瞽。","清游怀清标，所恨隔笑语。","茅庐新塈涂，户牖木仅斧。","剧谈伫公来，相望十里许。"]},{"t":"用宏见和复和一首","f":"五言古诗","c":["荒鸡号将晨，不改风及雨。","高贤两投分，定交从臼杵。","心期久弥坚，胶漆比孰愈。","有初顾隙未，卖友起中古。","五交有形状，孝标能训诂。","邈哉弹冠契，王阳知贡禹。","乘权献巧妍，失时辄轻侮。","管鲍贫时交，此道弃如土。","孟尝唾其面，愤懑聊一吐。","翟公书其门，薄夫常接武。","蹇予不知量，拔士偏寒苦。","见欺多校人，覈实失子羽。","归来蓬蒿园，吊影甘穷处。","知旧弃如遗，那复见比数。","谁知荆州丞，厚德能克举。","任安穷不去，平仲久更睹。","诗文连慰藉，词锋设宾主。","剡藤快展读，如坐对谈麈。","惜哉华国文，乃以观矇瞽。","舂容写河汉，寒窘笑三语。","才凡特俎豆，德薄更藻斧。","玉卮实无当，深恐累称许。"]},{"t":"海昌从中散兄游硖石东西山及赞山而别兄独游黄湾诸山寺宠寄三诗因追述前游却寄","f":"五言古诗","c":["相从十日欢，预恐别泪滴。","重谋访林壑，庶复延晷刻。","好山尘一舍，何惜蜡两屐。","东湖浸坤轴，浩荡鹍鹏击。","方舟稳睡馀，帆已收硖石。","东山号紫微，数殿耸金碧。","我祖鍊金膏，井湫湛寒色。","飙轮已仙去，千古留玉液。","当年善逝师，福壤眼独识。","上方子亭高，俯睨众山脊。","空濛云海宽，想像人境隔。","夜投涵虚阁，万籁森已寂。","软脚旋呼尊，亦复两颧赤。","黎明登西山，岌嶪动人魄。","华榜揭灵池，审公存故迹。","高堂坐白衣，巍巍妙智力。","道傍两精舍，联步遍游陟。","赞山特超峻，四双旧飞锡。","绿猗环高竿，苍髯矫千尺。","吴越峰峦秀，罗列在几席。","情赏未云厌，六龙俄已昃。","转溪遂分袂，恻怆不能食。","还家得诗筒，妙语粲珠璧。","具载黄湾游，恨不逐飞翼。","流光信驹隙，薄宦只鸡肋。","他年倦招寻，画图追旧历。"]},{"t":"硖石寺闻系猪明不能食","f":"五言律诗","c":["夜闻刺豕声，哀号欲趋死。","黎明肉入馔，念之难启齿。","口腹我可赊，性命彼所恃。","右军惋烹鹅，东家嗅供雉。"]},{"t":"七月一日招道祖剧饮","f":"五言古诗","c":["长卿已倦游，十年安泽国。","越鸟巢欲南，鹧鸪飞懒北。","会予亦蹭蹬，从子寄岑寂。","有酒时相邀，欢饮终未剧。","今当大火流，似闻姊丧释。","羽书静追呼，乐禁通考击。","扫除北窗凉，招速东床客。","暂勤车骑都，来辍春秋癖。","白啖苦无赖，红颜因暂惜。","畦蔬撷菘韭，园果剥梨棘。","金齑荐子鹅，银条脍玄鲫。","弓弯舞袖宽，珠贯歌声激。","景升陋三雅，淳于能一石。","拟取醉辖投，慵持诗烛刻。","浮生百年幻，且尽一朝适。","莫待佐稽山，对案空相忆。"]},{"t":"诸人见和复次韵","f":"五言古诗","c":["渊明事独往，谋酒不谋国。","引壶自酌罢，高卧幽窗北。","孤松供盘桓，五柳伴幽寂。","时赴中道邀，未觉体小剧。","八旬弃县令，忻若重负释。","安石登冶城，清谈工剖击。","竹林事游燕，百金费群客。","丝竹聊写情，副此杯铛癖。","岁晚白鸡梦，颓龄天不惜。","二士俱好饮，世运属艰棘。","身今扫閒轩，红蕖荫鲂鲫。","远挹环峰秀，下临湍水激。","得酒且尽欢，何人寿金石。","不如更添烛，夜漏淹晷刻。","醺酣便逃禅，酩酊非阏适。","从教醉谬误，黎明不能忆。"]},{"t":"次韵章婿道祖倧山居","f":"五言古诗","c":["我本丘壑人，负乘辄致寇。","归来卧湖海，梦断三接昼。","尚馀忧国心，带眼日惊瘦。","腾装居景山，飘飘云出岫。","门无长者辙，相见谁肯就。","吾甥相国孙，款我裹粮糗。","禅关有圣解，已语则无咎。","两庵同相攸，卜邻殆天授。","登盘无槟榔，客居必见宥。","富贵应自知，不询唐举寿。"]},{"t":"病起二首 其一","f":"五言律诗","c":["春风散顽阴，我亦除积痾。","客居有园林，得暇辄一过。","残梅雪尚积，曲沼春已波。","傥或不近酒，如此推迁何。"]},{"t":"病起二首 其二","f":"五言古诗","c":["人生身后名，孰得还孰失。","岂若一杯酒，聊复得永日。","如何杜陵老，感难百忧集。","不饮孰忘忧，饮多或生疾。","惟其疾之忧，已矣两相直。"]},{"t":"立方和韵复和一首","f":"五言古诗","c":["属疾大废食，始进一麦麻。","客至阙均礼，呼儿办瓜茶。","冷落乏胜事，病苦将日加。","儿曹解人意，为泼闽岭芽。","山深生意足，香味冠百嘉。","依稀仙掌露，彷佛石桥花。","过盏谢新法，失杯戒憎蛇。","甘我舌三寸，浇我书五车。","馀沥均学子，少长各有差。","何须待鞠卺，此段固已佳。","人生草头露，迅晷堪惊嗟。","适意贫亦乐，钟鼎来何赊。","今朝复何幸，濯暑分流霞。","苏息问苍生，欲泛牵牛槎。"]},{"t":"钱氏通惠泉","f":"五言古诗","c":["山翁彻骨清，日饮一瓢水。","天公隐其穷，殆将贻石髓。","先敕西神君，一派疏清泚。","初惊石罅出，盈科来未已。","其潴为渊潭，其汇则沼沚。","酌比九陇泉，饧味参差是。","一瓯紫笋春，牙颊留甘美。","馀波共濯缨，溅沫邀洗耳。","山中有异事，喜甚屐折齿。","长安昊天观，秦吴隔千里。","妄云脉络通，道人真疏矣。","寄语赞黄公，未应停水递。"]},{"t":"谢兴之饷鱼肉二酱二首 其一","f":"五言古诗","c":["贫厨不举火，素拙没与乾。","拾煤未为饥，犹有食一箪。","拜嘉欣二酱，顾尚阙晨餐。","快啖乱蒸肫，那学武子奢。","瓶中乏储米，请粟望子华。","佳醢得新味，羞豆应当加。"]},{"t":"谢兴之饷鱼肉二酱二首 其二","f":"五言古诗","c":["盎盎鹅儿酒，风卮起微浪。","何以侑芳樽，莼羹调得酱。","彘肩与鱼乙，佳惠过台饷。","黄雀酿披绵，江鲟斫玉板。","对之无留觞，固已号佳馔。","持此配藜羹，更增贫士赧。"]},{"t":"送同郡识上人游圆觉问道慈受","f":"五言古诗","c":["道人独往韵，半生服行衣。","专门施氏易，编脱屡绝韦。","文词粲藻火，片语不救饥。","弃家学心法，感叹悟昨非。","两年饱三白，屏弃甘与肥。","南行访道师，芒屩常轻飞。","侧闻长者寺，塔庙俱巍巍。","堂堂第一代，龙天共瞻依。","腾装来见语，舍是将安归。","勉旃叩玄旨，心花发清辉。"]},{"t":"东庄院","f":"五言古诗","c":["此君如佳士，得一不为少。","如何弥岗峦，十里青未了。","泉源湛山椒，红亭藏缥缈。","奔流泻万丈，穿林下萦绕。","居僧惜泉出，少借作溪沼。","冰霜溅沫乱，琴筑仙音杳。","水竹自莫逆，独厌逋客扰。","我亦愿结交，禅房寄深窈。","门前石盆潭，奁镜澄不挠。","寺后仙人壁，崚嶒插云表。","卜游已经年，此志幸不夭。","菟裘在何许，清境吾将老。"]},{"t":"中秋无月与伸仲饮书斋书呈伸仲","f":"五言古诗","c":["我生不如意，十事常七八。","穷巷属中秋，乃有长者辙。","相逢急呼酒，坐待盛满月。","那知天所閟，不吐冰轮洁。","王孙神肤清，与月真莫逆。","牛渚舫中人，武昌楼上客。","千古明月句，腹中无一阙。","我穷辄相累，昏灯照愁绝。","窗蕉响疏雨，杯负琉璃滑。","岂无仍圆夜，又恐间何阔。","呼童歌呜呜，一笑助耳热。"]},{"t":"送伸仲归漆塘以语及君臣际经书满腹中为韵十首 其一","f":"五言古诗","c":["侨居始定交，寄诚用缟纻。","命驾轻千里，次亦推嵇吕。","衰俗日益偷，此道弃如土。","如何五载间，七返慰羁旅。","峥嵘听崇论，璀璨惊韵语。","江湖风浪高，愧子蛟龙苦。"]},{"t":"送伸仲归漆塘以语及君臣际经书满腹中为韵十首 其二","f":"五言古诗","c":["家贫困百须，禄廪不时给。","接淅不渍糠，孤斟但饮湿。","长者车辙至，园蔬亲掇拾。","主礼不如意，八九更论十。","牛心饷会稽，猪肝售安邑。","兹事固么么，力亦不能及。"]},{"t":"送伸仲归漆塘以语及君臣际经书满腹中为韵十首 其三","f":"五言古诗","c":["聚书三万卷，断自典与坟。","籯金固已多，是家那得贫。","平生谢杂好，童习至白纷。","幽经与怪牒，一一储心君。","坐令说今古，奋袖真如云。","何当过藏室，手披至宵分。","时时咀熊胆，辛苦以佐勤。"]},{"t":"送伸仲归漆塘以语及君臣际经书满腹中为韵十首 其四","f":"五言古诗","c":["君家髯御史，百疏婴龙鳞。","死喜作忠鬼，生甘为旅人。","高节渠无继，从子盖其伦。","危言对便坐，肮脏不顾身。","重道轻禄仕，无宁常隐沦。","它年青史上，牵联书直臣。"]},{"t":"送伸仲归漆塘以语及君臣际经书满腹中为韵十首 其五","f":"五言古诗","c":["潜山赋归来，卜筑聊自憩。","岩壑发天藏，桐竹如手蓺。","寒泉西神派，那复问水递。","割甘饷儿女，伐木课童隶。","意行及趺坐，宴然契真际。","诚从古人求，三隐真可继。"]},{"t":"送伸仲归漆塘以语及君臣际经书满腹中为韵十首 其六","f":"五言律诗","c":["中年灯火读，阅遍汗简青。","岁晚得奥境，领略在六经。","肯薰班马馥，要续丘轲灯。","只今未康济，斯人尚郊坰。"]},{"t":"送伸仲归漆塘以语及君臣际经书满腹中为韵十首 其七","f":"五言古诗","c":["乱后等蓬转，风雨摧敝庐。","寄身菰城南，诛茅缚幽居。","家山在何许，清梦时一如。","南鸟每怀越，北马常嘶胡。","天狼今未落，中原犹羽书。","归欤不即赋，此心耿朝晡。","一廛肯相容，卜室终桑榆。"]},{"t":"送伸仲归漆塘以语及君臣际经书满腹中为韵十首 其八","f":"五言古诗","c":["失势水投石，得时山压卵。","富贵亲眷稠，贫贱交情断。","叔世浇薄中，风谊如君罕。","生涯一舸风，何门不堪款。","龙坂不著脚，乃数访幽散。","语离大匆匆，寸心常不满。"]},{"t":"送伸仲归漆塘以语及君臣际经书满腹中为韵十首 其九","f":"五言古诗","c":["皦皦常易污，容容每多福。","为嫌狙赋三，乃作龟藏六。","平生经纶手，都在十围腹。","似闻纱笼人，尽力欲推毂。","柬之今已老，鹤头来要速。"]},{"t":"送伸仲归漆塘以语及君臣际经书满腹中为韵十首 其十","f":"词","c":["顷年官黄冈，清俸缘手空。","饱暖到茕独，吾宁守其穷。","朅来漆塘山，?稏收横纵。","自言畏多累，不复爱亩钟。","负郭鄙苏子，沉舟似庞翁。","绝胜南阳人，辛苦耕隆中。","遗后但清德，有子人中龙。"]},{"t":"明日元举赴召见别用前韵送行","f":"五言古诗","c":["吾君急升平，元凯登二八。","赤墀拥豪俊，青云启涂辙。","岩居及川观，号召无虚月。","徵君笔瑞世，制行圭玉洁。","向来端神羊，不畏龙麟逆。","峤南归兴动，只作数旬客。","迹虽遁烟壑，名常蔼云阙。","果膺尺一书，赴陇催装发。","遂恐长乌府，席与群工绝。","眷言国步艰，敢惮泥涂滑。","牛刀剸繁剧，鹏翅摩空阔。","相期扶中兴，何止得官热。"]},{"t":"丁巳游大雄寺有陈朝桧","f":"五言古诗","c":["古殿藻井高，榱桷穷壮丽。","黄金四佛榜，煌煌曼卿字。","廷中桧异状，封植天嘉岁。","直干龟鹤年，樛枝龙蛇势。","阴森历九朝，知阅几兴废。","石根青铜柯，孤高方得地。","应笑凡草木，俛仰见癯瘁。","缅怀陈季年，三阁事瑰异。","后庭唱未阕，已作堕井计。","独此岁寒姿，与佛常阅世。","寄谢青牛宫，勿轻大雄寺。"]},{"t":"赭山承庆报慈禅院刘希范资政坟寺张参预为神道碑","f":"五言古诗","c":["故人具鸡黍，相携登赭山。","松桂蔚回舍，上已烟霄干。","阴风起天籁，误听号惊湍。","新寺粲碧瓦，突兀数十间。","君恩锡香火，以报顾复艰。","亭亭无愧碑，银钩墨初乾。","蓼莪避顾孝，汝坟起周盘。","罔极畴不念，致此良独难。","彭城廊庙姿，报国剑锋寒。","末途禦魑魅，鸢堕隔生还。","荣枯信反衍，谁能保常安。","徘徊积庆堂，老鼻一辛酸。"]},{"t":"戊午出长兴郭泛西溪至清果院","f":"五言古诗","c":["朱藤花堕影，罨画因名溪。","林壑莽参错，鹈鴂挟春啼。","刺船未云久，眼明古招提。","入门赤泥亭，石梁亦可跻。","佛殿制淳古，凌空飞拱枅。","凄其念陈祖，此境尝幽栖。","虾滩弄竿线，龙卧聊蟠泥。","一朝风云会，起舞随荒鸡。","兴王岂细事，荒陵出金犀。","贤愚同一丘，莫厌青鞋胝。"]},{"t":"戊午次吴山解空院乃端师子道场是日上巳呈法中禅老","f":"五言古诗","c":["寻幽勇鼓枻，兹山初问津。","云烟落吾手，若水清潾潾。","苍官旧千章，类不赦斧斤。","以兹海藏涌，突兀干苍旻。","独馀三大夫，攲盖皴龙鳞。","下阅往来辈，蜉蝣不知春。","迎宾上人者，貌古意甚真。","岂惟嗣老端，势到粲忍亲。","陟巘既幽绝，飞谈复清新。","何庸浥寒波，更祓元规尘。"]},{"t":"己未次广惠院","f":"五言古诗","c":["下若水沄沄，佛寺古邑西。","开帆但五里，不到将噬脐。","怀古展清眺，崇阁聊攀跻。","法生有鼻祖，乐此山与溪。","自言孙子贤，兹地兴王基。","霸主受九锡，二纪承梁齐。","空馀阳乌阜，石人卧荒蹊。","绿满天随家，岩花伴幽栖。","留传杞菊堂，墨妙悬榱题。","秀色有他岭，招寻更杖藜。","山林且放诞，边城多鼓鼙。"]},{"t":"次吴粹老观我斋诗","f":"五言古诗","c":["立我谨外揵，逐物戒内热。","樊然辨物我，此意犹屑屑。","是身本虚空，何者为六结。","虽慧念不起，虽定照不灭。","无我与我所，观亦于何设。","右臂弹已化，左肘柳方蘖。","顾君进此道，遗我自朝彻。","不见鲁东家，意与我俱绝。"]},{"t":"同子充游尧祠见交代李行正诗追用李太白旧韵因亦次韵呈子充","f":"词","c":["俗物败人意，作吏七不堪。","朅来东蒙遇欢友，角立杰出推江南。","英材百汰挥利刃，夷量万顷澄寒潭。","弱龄文采照金殿，荏苒立境衣犹蓝。","铜章来踏瑕丘鼓，邑屋欢康无疾苦。","春风郊外正酣酣，笑指丛祠两骖舞。","猛抛簿领乱回回，戏看油碧声如雷。","不遣韶光浪湮灭，桃已蒸霞柳飞雪。","超然危立俯河干，抱城清泗鸣惊湍。","谪仙秀句但碑板，无复真迹龙蛇蟠。","君不见聪明文思抚寰海，四表上下腾光彩。","破椽欺魄炉无烟，豪气英风亦何在。","荒郊遗趾望中来，遐想千古令人哀。","祖龙巡幸亦琐琐，从臣徒向苍珉开。","豪华岂复灵光殿，峻峗谁知季武台。","耿耿星河挂窗牖，未跨归鞍犹捧手。","同门早岁气横秋，年大饥寒依秫酒。","俗儒醒醉尚不分，金马玉麟名远闻。","小县鸣弦烦卓令，冷阁问字疲子云。","五斗不归俱委琐，邂逅为僚天赞我。","金兰缟纻未足誇，嵇吕命驾何其赊。","官寺相望无百步，泮林正对河阳花。","坐令庄舄忘吟越，亦复无心存魏阙。","蒲酒相从未有涯，祭灶请邻才一月。"]},{"t":"记梦诗 其一","f":"七言古诗","c":["颐堂昼卧清且閒，了无尘霿来相关。","俄然正梦半山老，练裙葛帔泉石间。","抵掌称谭因饷砚，微凹浮墨光如电。","自言翻经视草时，落纸云烟皆倚办。","山颓梁坏空遗祠，觉读其书寐见之。","勉令勋德复蔼蔼，佳兆若此真非衰。","少瑜昔梦青镂笔，江淹重锦完成匹。","明当辞艺骤惊人，千里从今期一日。"]},{"t":"记梦诗 其二","f":"七言古诗","c":["元丰功成身退閒，钟山小筑掩松关。","莘莘学子求卒业，说经闹若阛门间。","木铎兹文繄笔砚，紫绶垂腰眼岩电。","似闻一日置心猿，道德功名无不办。","配食孔庙时烝祠，子生其后不识之。","文章津源已默付，名爵岂待颜发衰。","向来李峤梦双笔，至今辞藻无伦匹。","纳鉴唾口难细论，谓言不信有如日。"]},{"t":"补之见和复次韵二首 其一","f":"七言古诗","c":["仙曹无事身得閒，午睡绝恶呼当关。","榻施籧篨独展转，梦觉不离周孔间。","官出砚州初乏砚，过眼罗纹如过电。","半生用一即墨侯，颇欲易之贫不办。","旧闻梦砚湘君祠，乃今神异真类之。","秣陵真儒岂虚授，文字之祥昌不衰。","擘笺亹亹称名笔，正始微言欲俦匹。","终当辞藻瑞朝廷，更请焚膏勤继日。"]},{"t":"补之见和复次韵二首 其二","f":"七言古诗","c":["逸骥未遇虚王闲，盐车垂耳犹间关。","梦中一眄逢伯乐，遗以旧物惝恍间。","斧柯山神护珍砚，采琢往往兴雷电。","欲求潜璞满书簏，顾岂咄嗟便能办。","祷求苦用中牢祠，何如假卧辄得之。","池塘句好有神助，文字格力何因衰。","莫嗟筮仕困刀笔，聘材行即肩群匹。","速将妙语醉衰翁，鸂鶒飞滩知不日。"]},{"t":"从人求鳆鱼","f":"七言古诗","c":["海邦邾莒固多品，此族称珍乃其伯。","沈泉湘瀹付饔宰，姜桂煎调奉佳客。","视书已觉明病眼，点酒偏能醒醉魄。","君看忧愤不眠人，快啖取厌亦何择。","岂如吾曹饮文字，舆台不复沾馀沥。","昔官馀杭饱下箸，两载杯盘厌凡核。","朅来瑕丘问鲑菜，樽俎遍索未云获。","愿从褚公弃千万，免使刘郎鞭二百。"]},{"t":"刁马河上书事呈提举张圣用","f":"七言古诗","c":["稻人掌稼存周书，荡以沟洫蓄以潴。","为田一夫顾尚尔，有大于此其亡诸。","所以当时多善岁，黍稌高下无莱污。","史公引漳变舄卤，郑国注洛通廞淤。","寂寞井地已不复，二子兴利犹居居。","常平新书出圣考，岁积羡入为留储。","毫釐不以给公上，补助力役宽农夫。","意谓舍此欲富国，不几缘木求渊鱼。","猗欤吾皇始即阼，骏惠成宪追前摹。","民田利病特经意，诏俾海县交修予。","刍言舆议满青匦，论及刁马尤勤渠。","一劳暂费不足惮，要使长利相乘除。","水衡衔命出护役，使节适野同伻图。","劝勤警惰诏赏罚，尺一径下随都俞。","择材分干自不乏，犹如采芑从菑畬。","薨薨畚插事疏凿，坎坎钲鼓催勤劬。","伍符尺籍用兵法，保受团结从州闾。","施功堑中每绝蚓，得肉道上时衔乌。","河流广深事股引，清波涨绿涵灵胥。","劝农使者旧京兆，眉妩曾画闺房姝。","鲁邦都尉古循吏，谋视韩许直庸奴。","经营土功费心画，埤益王事成仙臞。","清明不归对花柳，独冒埃壒驰轺车。","香名巍巍镂翠琰，绩用蔼蔼飞皇都。","横流不复灌旁郡，万室按堵安田庐。","陪京沃壤袤千里，旱乾水溢从今无。","谁言酾渠百世利，政在起役三旬馀。","荒功经始自勿亟，烦尔讫事歌骊驹。","役夫云翔指千万，北返曹濮南青徐。","愿修厉禁比川泽，张官督察称衡虞。"]},{"t":"谢人惠笋","f":"七言古诗","c":["箨龙初萌豹文点，味阙盘飧心正慊。","二公好事为髡锄，一日分甘香掩冉。","小靳全胜沈道虔，纵取何殊范元琰。","趣令庖宰事烧煮，未怕旁人呵聚敛。","白醪赤米最相称，紫蓼绿葵当少贬。","验长须知韩老嗜，称冤却笑卢仝俭。","遥怜萌出盛家林，岂不怀归畏官检。","愿君继饷走舆隶，莫遣烟篁拂崖广。"]},{"t":"喜元举归","f":"七言古诗","c":["溪东作舍已盖茆，溪西筑庵新立栋。","水云参错出十里，妙寄方嗟无与共。","忽闻故交还五岭，聊喜居邻依二仲。","台评早岁冠神羊，儒馆文华推白凤。","诏除每下辄避宠，才术小试已惊众。","炎荒虽云去国远，皇华要是为时用。","故为怀归逐我辈，露章求免疲护送。","自言峤南官不恶，峻峰危嶝频飞鞚。","挽葛屡上罗浮颠，披云亦到朱明洞。","看山却忆家林好，夜夜幽栖来旅梦。","而今归隐寄天放，却忆修途真定痛。","猿鹤相向为家禽，松菊未荒怜手种。","碧鲜脱箨高绕屋，白堕敷醪香出瓮。","从今莫厌数招寻，持鳌共费宫祠俸。"]},{"t":"试建溪新茶次元述韵","f":"七言古诗","c":["舶舟初出建溪春，红笺品题苞蒻叶。","低昂轻重如美人，等衰铢较知难躐。","格高玉雪瑩衷肠，品下膏油浮面颊。","太丘胸中有泾渭，包裹携来充博帖。","稍发下驷已惊眼，香味高奇光炜晔。","不肯花前杀风景，凭花为谢穿花蝶。","更看正紫小方圭，价比连城真称惬。","病渴羌人洗烦滞，好睡兼旬便愁摄。","异时风流贵公子，喜悦藏珍令口嗫。","莫辞七椀搅枯肠，有酒沽君夜烧蜡。"]},{"t":"次韵去非谢前教授饷泽州瓦砚","f":"七言古诗","c":["锡花蒸成一抔土，联坳即墨元光舞。","飞鸳馀韵照文房，吕翁心机同刻楮。","高平沃壤真土膏，砚与龙尾为朋曹。","刚柔得中不坯甈，共推妙手能甄陶。","郎官小样知名久，何须对面供十手。","讲郎尚有千载人，要此编摩论臧否。","请加什袭传后昆，阿买不独书八分。","纱帷昼静棐几滑，克肖鼻祖能缀文。"]},{"t":"次韵去非题紫逻洞","f":"七言古诗","c":["一麾谬作东诸侯，邂逅两玉陪遨游。","引泉叠山作竹洞，持以奉客充淹留。","㶁㶁清流出潭底，辟疆万个那胜此。","奇礓文六照幽亭，雅称幼舆岩石里。","人所应无君尽无，哦诗拥卷穷晨晡。","指物程形直题署，便欲相称诗董狐。","云水相从乐复乐，汝阳太守自宾幕。","不用飞章乞会稽，耸秀交流看岩壑。"]},{"t":"次韵去非梅花","f":"七言古诗","c":["造化小儿心恋嫪，偏向冰花施巧妙。","冷禁霜带晓寒飘，清宜月缀微云照。","已与鸣鸠传酒信，更乞游蜂供蜜料。","交情万里寄春色，度曲五更吹怨调。","半树临溪抵死香，一枝倚竹嫣然笑。","寒姿疏影太幽独，静女贫姝真窈窕。","世言嘉卉出灵山，我疑异种来圆峤。","肯挑俗子炫秾丽，只约骚人伴吟啸。","少陵牵兴催衰白，广平被恼回刚峭。","径须相过寿此花，市远无肴只藜藋。"]},{"t":"次韵去非留别","f":"七言古诗","c":["馀子碌碌不足数，太丘晚出吾所许。","淹盘此境未金马，邂逅相逢慰铜虎。","与超宗语不知寒，从季远游那觉暑。","祥琴皋月歘戒行，征马谯门聊出祖。","平生种学与绩文，自信扶圭兼缀组。","分无桃叶把歌扇，只有松枝当谈麈。","行装未办缠头帛，衣食何施择木羽。","从来文豹深隐雾，此去老蛟真得雨。","长卿蜀肆初涤器，伯鸾吴庑曾舂杵。","青云直上不作难，那复笑人忧邓禹。"]},{"t":"喜宗丞侄病愈","f":"七言律诗","c":["向来闻汝拙将理，五日寝瘵未药喜。","医良未遇肱三折，爱切徒劳夜十起。","欣闻安泰风愈檄，莫叹清癯肉消髀。","径须营度还诗债，要看笔端翻峡水。"]},{"t":"奉同李倅安上赋崔白沐猴杏花","f":"七言古诗","c":["空山无人春风骄，扑扑晴杏开香苞。","岩深谷峻无与赏，攀枝腾踏帷飞猱。","大梁崔白旧所见，绢素落手因挥毫。","巧为红艳狼籍势，扑蔌幡洒归蓬蒿。","王孙惜花有深意，预忧雨横兼风豪。","故来跳触看零乱，妙思临写形无逃。","贵人锦囊旧藏贮，文闱传玩丛英髦。","东平儒仙首留咏，诗价与画相争高。","直云何用辨真假，径须对此呼香醪。","谁知真花却时暂，不如丹粉还坚牢。"]},{"t":"高君贽兼数职奔走疲甚以诗劳苦之","f":"七言古诗","c":["晓鼓逢逢天未白，呼火摄衣干典客。","青衫手板阶石前，磬折擎拳若无骨。","还将束矢听情伪，更向团丝分枉直。","糟浆逆鼻走兵厨，播糠眯目司平籴。","翩翩轻舆行若飞，濯濯单纨汗如涤。","趋局何曾过八塼，端居未暇移百甓。","归家往往犬迎吠，得肉时时鸟攫食。","长材要自万鹏程，初筮聊淹一鸡肋。","径须黾勉弹其冠，未用低佪尤此帻。","左冯旧事今复继，敏手州人惊霹雳。"]},{"t":"邑尉姜补之枉诗甚宠率尔酬和","f":"七言古诗","c":["去年诏锁春官闱，桓桓文阵如熊罴。","激昂辞章争自售，猎取豪俊几无遗。","五更榜帖乱人鬼，九衢姓字奔轮蹄。","维时谬从宗伯后，喜子入彀名高垂。","枫宸胪传预供奉，杏苑开宴常追随。","那知岩邑大如斗，邂逅联事同劳疲。","民顽奊诟号难治，心怯畏缩将安施。","幸蒙干略整纷冗，间以文义相娱嬉。","忘形未肯遽尔汝，执礼乃或论生师。","固知风味去人远，九牛何止争毫釐。","平生最喜我辈士，角巾野服同委蛇。","尔来亭午已休吏，五百弥月閒鞭笞。","城南桐竹富萧瑟，城北溪涨清沦漪。","颇愿吾僚哀老子，遨游使得时伸眉。"]},{"t":"送许师德","f":"七言古诗","c":["访我金溪船系柳，一杯醑我真天酒。","腾装欲赴清油幕，才得伸眉俄振手。","家声文采照东南，洛师吴郡乃所监。","羔纁继辟不容避，聊脱黄帽穿征衫。","元戎器业光鼎轴，百万貔貅为部曲。","仰分忧顾新登坛，慎柬英僚佐推毂。","平生韬略摅一朝，伫看烽静无氛妖。","将军三箭天山定，千群塞马嘶风骄。"]},{"t":"少川兄贫悴甚见属求寓馆未遇好事者聊作诗以寄因以速之","f":"七言古诗","c":["我兄弱龄推了了，手不停披今发缟。","人中滞论能立判，笔下陈言皆力扫。","多如鸡蹠叹积学，大似牛腰看属藁。","败絮自拥不言寒，书床坐穴那知老。","逆旅无人识马周，除舍何当馆孙宝。","水波未合急相过，漱醪聊缓忧心捣。"]},{"t":"寄题吴江王文孺解元臞庵","f":"七言古诗","c":["臞庵散人筑隐居，自称山泽之臞儒。","邀风贮月有亭观，以道自广何其臞。","三江雪浪鱼龙窟，千古浮天仍浴日。","乍吞涯涘归醉胸，时卷波澜入吟笔。","天储此景非寒窘，经营杰观规相准。","万株苍石云斸根，十顷红蕖波照影。","异时璧沼摇毛锥，同门太半通金闺。","一班一级何足道，赋归有此知为谁。","境清恍与尘寰隔，彷佛天随旧行迹。","闻道朱黄近笔床，定有丛书增笠泽。"]},{"t":"次韵庆善九日","f":"七言律诗","c":["舍南自灌五亩园，满种黄花待亲识。","明朝酒熟当寿君，卷白不许馀涓滴。","湖海浮家作寓公，醉醒幸与骚人同。","一座尽倾尘表物，不须举扇障西风。"]},{"t":"再和庆善","f":"七言律诗","c":["但将诗酒乐重阳，呫嗫深嫌程不识。","已呼明月倒芳樽，更浥沧波供砚滴。","多闻素仰百六公，飘零邂逅笑语同。","明当数助击鲜品，鼻头出火耳生风。"]},{"t":"送庆善之江阴","f":"七言古诗","c":["南州地气真火维，午暑势若遭蒸炊。","风亭水榭不救暍，如何泛役冲炎曦。","四年遵路俱六月，叩门急义非君谁。","小蓬暑行分不免，著书暂卷春秋帷。","借船屡枉逸少字，质钱敢以班史辞。","一麾尚与数人共，西江得水知何时。","况复外事继婴扰，主孟频歌烹伏雌。","天其或者降大任，必先空乏其储赀。","老人索居寓泽国，蛙黾同处时迎医。","麦曲芎藭两未效，政须健论扶衰疲。","君今舍我那遽反，落寞何用伸吾眉。","大恐尺一亟招选，径从儳道趋天墀。"]},{"t":"嘲渊明代答","f":"词","c":["君不见七百石了曲蘖事，二千石充雀鼠耗。","浇肠果腹固有馀，糟丘米山何足道。","不如酒尽仍从酒家觅，瓶中粟空聊乞食。"]},{"t":"依韵和子有教授侄寄雪诗","f":"七言古诗","c":["空中纷霏谁剪水，夜半天窗明蜡纸。","天将奇宝借词客，使酒驱诗难但已。","红炉活火然松明，閒施博局呼明琼。","区中无此清绝境，疑是缩地来蓬瀛。","从来闻说三吴道，飘瞥郊原看最好。","且愿留为不夜城，挥戈却日还穹昊。","讲郎才韵今可人，闻客欲至颜津津。","急扫阶庭施木屑，跋马去作陶家宾。"]},{"t":"卫卿弟和诗佳甚复和一首","f":"七言古诗","c":["俗人雪句如翻水，陈言堪吊剡藤纸。","子诗清如扇上赞，使我三叹不能已。","妍姿与雪争轻明，白战不道飞瑶琼。","西神山畔芙蓉水，好招烟艇浮澄瀛。","千岩不必山阴道，何处轻飘看不好。","百觚判断速呼客，莫待睍消还畀昊。","天储此景娱閒人，贮瓶泼茗甘流津。","茅檐从此便归隐，不待人呼祁孔宾。"]},{"t":"卫卿弟赋诗见贻和答一首时有从军之兴","f":"七言古诗","c":["我如老屋人多阅，肮脏如君真可悦。","长涂未骋驹伏辕，窘步无堪鲋依辙。","诸贤衮衮位华显，独子栖栖困岩穴。","何妨虎子聊一探，况是龙泉未虞缺。","前时羹稀客告去，尔日瓶空粮又绝。","不缘闵已赋牢愁，独为伤时拭清血。","燕颔食肉骨素奇，龙额封侯计非拙。","勉旃矍铄出据鞍，收卷毛锥从此决。"]},{"t":"次韵郑维心游西余山","f":"七言古诗","c":["云巘瑰奇甲震州，不须幽境更旁搜。","从来知是通侯国，此段方从胜客游。","闰岁春迟空水树，雨时溪涨失沙洲。","吾衰久矣欲何适，更为前山一上楼。","顾余峰好锁云烟，入寺窥临信所传。","衣袒右肩从衲子，屐除前齿陟山巅。","一杯相属真宜釂，四者难并偶幸全。","亭号弄云谁作记，紫枢当日笔如椽。"]},{"t":"明月峡","f":"七言古诗","c":["李庇山记皮陆诗，纪述茶事真历历。","枕流亭北池七里，万仞插天双石壁。","悬崖倒挂天银河，武敏尚存西楚迹。","昔贤招寻多好事，例以姓字刊岩石。","青琼绿髓茶始生，报春鸟鸣山昼寂。","茶民研膏柏黑粘，香焙凿山深二尺。","急程苞贡御帘开，宫娥进水倾寒碧。","只今玉食岁不供，旧事独有山英识。","羁人水厄不厌数，耿耿不寐几通昔。","他日重来觅旧题，应叹流年如矢激。"]},{"t":"工部兄新治小阁垒土为火炉戏作劝召客","f":"七言古诗","c":["简许开尊杀青竹，俎有肥羜簋饛粟。","招呼未听洗盏声，故复吟哦小诗促。","能使将军赏不贫，请召宗姓仍及身。","拥炉便是入窟室，于粲洒扫情无文。","我今愁如居广柳，万斛量之应更有。","内典暂辍算海沙，群经尤慵开户牖。","政欲酣畅融心神，村郊鱼鸟皆来亲。","不忧坐上无武子，群从一一天麒麟。"]},{"t":"大父通议无恙日开轩燕处有桐孤峙因名琴轩初不措琴尝作记叙意而偶失藁本故今家集不载比者兴之侄阅故书得之见贶喜而成咏呈六兄工部兼简弟侄","f":"七言古诗","c":["峄阳奇轩高参天，对以华屋名琴轩。","轩中寄傲隐君子，方瞳鹤发臞儒仙。","閒中默契丝桐理，不待徽弦出宫徵。","柳恽笔捶佐属文，渊明手抚聊寄意。","一篇叙此藏巾箱，歘尔六丁下取将。","世无安世谁默识，才异束晰孰补亡。","神物护持今复出，数纸蛟蛇亲手泽。","敢辞援笔补遗编，谩致区区贻厥力。"]},{"t":"诸人各见和复和一首","f":"七言古诗","c":["我祖还笏归乐天，不羡戴冕兼乘轩。","扫门笑傲寄元趣，一龛相对惟金仙。","辞藻翩翩能析理，字字清奇中商徵。","响泉韵磬初不施，见色闻声自真意。","从来家学传青箱，禄侈万石今方将。","此篇不愁暂飞去，天相斯文终不亡。","孙曾秀杰今层出，馀庆仰承君子泽。","莫言临绝似获麟，请看笔头扛鼎力。"]},{"t":"沈必先殿院用策字韵赋诗见赠谨依韵和时居盛林","f":"七言古诗","c":["菁山遽用檀公策，水村来作浮家客。","五年霄汉隔音尘，此假相逢喜折屐。","荒陂难觅钴鉧潭，胸中丘壑有人杰。","乌台坐逼痴床南，见事风生勇成癖。","逆耳争先贡皂囊，造膝仍频对宣室。","只今道梗淹荒村，汲直未肯侪公孙。","时平已见龟墨食，尺一行催觐文石。"]},{"t":"蒙维心示谢必先尚书饷笔佳什时维心方刊正三国史辄依韵攀和","f":"七言古诗","c":["谷口之孙材刃铦，如针处囊立见尖。","平生苦心在坟索，入月犹未高骑蟾。","若嫌寿史六十五，论次未必三长兼。","与时讳恶难偻指，为米溢美堪掀髯。","浪言张华为辍笔，至今诋者口不钳。","因持众制事编削，管城虽老聊复拈。","明明褒讥淆泾渭，欲向素王师谨严。","已删卧龙无将略，过实仍刊诸葛瞻。","东阳尚书助述作，束颖分饷出宝奁。","自言宸廷夙沾赐，今以归奉馀不潜。","鸡距鹿毛青镂管，品制一一形标签。","昔冠神羊书白简，痛击奸佞如针砭。","并与书法奉君子，大书特书不可淹。","悬知南董奋直笔，首于三马诛奸憸。"]},{"t":"次韵王得之方池父子玩月","f":"词","c":["先生夜不眠，爱月真痴绝。","呼儿饮文字，桃黍聊一雪。","清光入酒堕胸次，照见万卷非涉躐。","商容颢气寒彻骨，况是冰轮圆不缺。","中宵影倒万顷池，上下金盘两澄彻。","广寒灵媛多飞琼，烟凝露暧收群声。","鱼冷跳波闻静岸，鹊惊绕树当前楹。","辞直道山来膝上，郎君吟兴纷纵横。","诗成父子定知已，门有佳儿真宁馨。","不须灵液玻璃盌，一梦瑶台亦非远。"]},{"t":"杨泰初权县丞数寄示诗文作诗纪谢","f":"七言古诗","c":["关西家世东都相，褫褐十年今始壮。","一官栖栖百僚底，众制翘翘万夫上。","忆昔曲台尸列卿，谬厕春闱惭哲匠。","英俊下沉势欲拔，文章横流期少障。","榜中上第溷元结，堂下一言惊叔向。","频蒙古锦倒清篇，更枉长须问无恙。","详观叹赏欲投笔，退恧粗疏堪覆酱。","吾衰文意已蹉跎，凤阁当求舍人样。"]},{"t":"程良器嘉量解元许为写照作诗求之","f":"七言古诗","c":["虎头千古丹青杰，谁言黠中有痴绝。","手挥五弦真胜诣，颊染三毫更超越。","自言四体媸或妍，顾与妙处无相关。","炯炯双瞳点圆碧，笔下顿觉神明还。","程郎言语妙天下，画复通灵能变化。","扫除俗骨画如诗，摹写天机诗似画。","竹斋溪屿数相从，似蒙儃儃窥尘容。","诋呵众史露拙迹，疑有心画藏胸中。","寒乡鼠目獐头子，葛帔练裙谢龟紫。","幼舆政自丘壑人，试为写传岩石里。"]},{"t":"次韵范昌龄庆新居","f":"七言古诗","c":["我家渺在澄江浦，泛宅来依白蘋渚。","客居十载席为门，上盖茅茨下榛楚。","迩来作舍倒归赀，聊为儿曹庇寒暑。","千岩万壑相妩媚，似以身尝为地主。","楼外烟霞邀吐句，堂中坟史供稽古。","岁晚居身可否间，簪裳束阁饶安閒。","深愧词人相俎豆，鹤书应不愧钟山。"]},{"t":"先君忌饭僧悟空兴之侄有诗和韵","f":"词","c":["君不见毗耶居士人天英，化佛亿万文室盈。","清晨香积一盂食，厌足一切紧法力。","又不见手捉麈尾生公庐，说经妙蕴几无馀。","岂惟缁素日会面，粉碎虚空雨花片。","我生归命海潮音，况复劬劳讳日临。","三孤遗像涕沾臆，建斋达观趋禅阈。","悟空谁是悟真空，门前灌木吟悲风。"]},{"t":"赠星洲僧了然","f":"七言古诗","c":["禅林古有一宿觉，讲席尝闻一遍照。","凡马十驾及骏骨，况子秀颖颜齿少。","星洲岩壑锁烟云，千柱浮空觉王庙。","似闻淬掌作书淫，乍或横肱究心要。","明窗净几学参玄，二涂一得可前料。","香浮牛首礼圆光，呗似鱼山胜长啸。","闻熏大士岂忘言，机锋嘿赞潮音妙。"]},{"t":"和陈简斋韵","f":"词","c":["马鞭虽长不及腹，山林朝市两角逐。","华堂谁挂元吉獐，坐使朱门变林谷。","龙章凤姿自有种，山野头颅未为辱。","长沙写真得天趣，下视冯尹皆奴仆。","君不见青州刘幡得异草，能遣死麇骨再肉。","又不见广平射麇变浮屠，因罢校猎投金镞。","两幅陵陂槲叶香，俦侣共乐春草长。","昂头妥尾无所畏，窘拘知胜触藩羊。"]},{"t":"依韵和兴之侄","f":"七言古诗","c":["一真那有黑白业，佛橐枉用为书箧。","人人反照自图成，说甚一花开五叶。","了无结习便超脱，因有挂碍生怖慑。","山鬼窟中求活计，玄关欲透知何劫。","匝天遍地自心源，若解承当真要捷。","树林水鸟皆法音，露柱幡竿光炜烨。","世上盲聋喑哑人，试问道师作么接。"]},{"t":"寄题伸仲芳美亭","f":"七言古诗","c":["渔舟一出桃源路，烟锁云埋迷旧处。","那知九龙有仙村，漫山灼灼花无数。","人言却老是此花，只今已似刘晨家。","微风披拂飞红雨，杲日照耀蒸红霞。","似闻花间新结宇，醉吟多是神仙侣。","更求人面相映红，我欲叩门求雪黍。"]},{"t":"圆复师将游四明用道祖韵作诗赠行","f":"七言古诗","c":["禅宗不减宿一觉，文性还同照一遍。","哑羊岂是一流人，漆瞳烂烂岩中电。","机缘未遇閟金提，云水光中挂衲衣。","定回时起橐驼坐，秀句一吐胸中奇。","过我郡斋那听去，衮衮谈玄侵日暮。","西风吹面作新凉，腾装欲指鄞江路。","一庵钱料山幽深，欲抛印绶聊招寻。","倦游归来问无恙，东第飘然正角巾。"]},{"t":"招道祖签判尝暑酎辱示佳篇纪事辄依韵奉和且约再冰酿云","f":"词","c":["君不见兵火连年扰江汉，一介荩臣无断断。","列城守将遁或降，那得捐躯颜与段。","鏖兵喋血八年间，西失平夏北折兰。","奔军知是何鸡狗，坐想飞将张与关。","草莽臣谋未云获，且复浇愁倾大白。","平时徒有扇障尘，一笑未辨须缠帛。","相邀聊共圣贤中，但愁烛跋鸱夷空。","沉酣不畏轻出舌，惊惧悬知不入胸。","午夜醉归闻踏月，林影滩声助清绝。","糟兵好向水村营，壑谷正为吾曹设。","儒生嗜酒多有之，高阳酩酊无所缺。","莫言酌我慎无多，休弹贺若唱回波，腾腾相送入无何。"]},{"t":"二十五日道祖沧浪亭落成召会","f":"七言古诗","c":["东园延袤不论亩，树梓成行俱楚楚。","方池瀰漫涨涟漪，藕花清酣娇欲语。","临流新筑沧浪亭，斧斤断手邀落成。","苏家风月旧无价，千金买得亭和名。","穹庐饮马吴江水，长洲万井红烟起。","齐云楼观委寒灰，那有相家歌舞地。","稽山别乘今豪英，肯将胜事颓家声。","青毡旧物今在眼，彷佛北牖仍东荣。","把盏聊为主人寿，乱离已往空搔首。","请看前日闹巫医，岂有閒情举樽酒。","朝来大火落南躔，已觉病骨苏凉天。","剩捣橙齑斫鲈鲙，全家醉倒秋风前。"]},{"t":"流杯","f":"七言古诗","c":["美哉洋洋曲流水，碧可染衣清彻底。","我倾山资结茅舍，两载经营端为此。","春风上巳一月前，小试禊事来水边。","胡床醉坐略少长，羽觞轻泛随洄沿。","道人护戒无酒欲，笑挹清波作醽醁。","崖蜜相和代引满，自言过免三十六。","随缘戏剧亦何嫌，胜游从来支许兼。","久知世味如嚼蜡，未应贪著中边甜。"]},{"t":"次韵道祖大水","f":"词","c":["君不见绿槐荫夏摇千门，移秧遍野缲盈盆。","天公忽作弥月雨，忧岁上勤黄屋尊。","我家茆庐劣容膝，随水倾摧非瑞室。","街衢生鱼堪佐饔，檐霤垂龙欲穿石。","仰天又见兴油云，乾雨误点波连村。","马牛不辩固其理，蛙黾同处何容论。","休叹栖苴接飞翼，林端会见宾红日。","木饥水毁傥时运，救灾行看恩洋溢。"]},{"t":"同道祖及子舍游茶山归因成","f":"七言古诗","c":["寒窗送曙鸡一鸣，寻山蓐食天初晴。","水口溪穷为停棹，步携东坦仍添丁。","虎头岩高山色好，竹舆遥睇眼为青。","花濑濛濛胜紫气，微花拂衽闻芳馨。","岌峨悬臼与天接，脚力欲趁飞猱轻。","此邦佳处遍寻陟，夫差所顾独未经。","兹游野服穿不借，自胜五马仍双旌。","忆昔贞元守修贡，木瓜堂庑辉山扃。","两邦歌舞竞姝丽，谷雨不许遨头醒。","只今金沙杂榛莽，空照华发垂星星。","近涧喧豗泉㶁㶁，远峰娇腻云英英。","山僧意勤苞紫笋，倾盖一笑无平生。","息黥补劓有甘寝，梦觉起作游山行。"]},{"t":"新池水涸股引于前溪辱道祖来观","f":"七言古诗","c":["吾庐新筑薰风堂，其下方池手亲掘。","畚插初无邻里相，垠隅那有波澜阔。","旱涸俄惊拆龟兆，灌输未免翻龙骨。","街南大浸卷滔滔，巷北小渠来汨汨。","胶杯忽觉水痕涨，抱瓮免嗟人力竭。","已怜红芰浃枯荄，更喜赪鳞救濡沫。","幽居胜事快先睹，上客高轩为轻出。","蛟龙好在且泥蟠，他年岂复池中物。"]},{"t":"初得庵基于青山用立方韵请道祖同赋","f":"七言古诗","c":["身閒那赠绕朝策，来作菁山数旬客。","结庵痛谢九流宾，轻重嫌人分履屐。","才通箭道菖蒲潭，幼舆政合居山岩。","斗健更须升绝顶，接天巨浸浮东南。","从来不办王济癖，石磴骑危甘脚历。","欲将土木化荆榛，坐叹清风来入室。","练裙葛帔居山村，共怪膏粱相国孙。","祝鸡为邻言不食，自此相从煮白石。"]},{"t":"道祖见和复赋一首","f":"七言古诗","c":["人言不饮第一策，况我携贫来作客。","破衣任笑频见肘，断鞋不办时新屐。","公材公望非丁潭，世人谁许瞻岩岩。","豺狼满道生理窄，立锥方卜南山南。","十年丘壑几成癖，澄怀坐想真历历。","难希蒋诩开三径，且学陈蕃事一室。","时危花柳自村村，未害含饴仍弄孙。","淡饭且安禅悦食，储钱更买奇礓石。"]},{"t":"大暑新居纳凉和小子韵","f":"七言古诗","c":["至后金柔伏日三，旱气焚宣势如惔。","火井涌沸烟生岚，鹤发遗老素未谙。","我居濒泽深眈眈，修廊飞庑贤僧庵。","薰然好风来自南，如甘露门开瞿昙。","如客怀冰吐清谈，有亭自雨临深潭。","不假凉草生毵毵，天日炎赫反所贪。","我穷储无石与甔，枵然饥腹空婪酣。","后皇矜怜百不堪，免使熟烂聊包涵。","王城衮衮穿朝衫，跨马挥汗流朱蓝。","独逃靡盬侍鱼泔，坐享逸乐扪心惭。"]},{"t":"用立方韵二首 其一","f":"七言律诗","c":["山村艰食宇昼合，斋钵相呼坐僧榻。","今朝瘦羊忽入馔，云是馂馀彻膢腊。","年大才疏合退休，尚玷恩华只自羞。","赏延亹亹来踵武，命服童孙尚羁午。"]},{"t":"用立方韵二首 其二","f":"七言律诗","c":["仕宦由来须遇合，未遇杜门宁穴榻。","尊无泛蚁浪经春，突有悬貆偶乘腊。","郡印还官得小休，桑枢席门何足羞。","幽居不羡裴掌武，绿野堂前桥号午。"]},{"t":"立方辟小阁附火兴之侄作诗劝会客次韵","f":"七言古诗","c":["吾儿玄学师老怀，严持月六八关斋。","新来五辛不入口，坐使妻叹生不谐。","自言丈室净名量，惟期禅侣来存访。","栗里岂独尊常空，亦乏秦声乱舂相。","朝来天雨瑶花霏，句如连璧来交辉。","鹿柈茶果亦易具，不尔恐致膏肓讥。","幻界政应频燕喜，酒尽为谋当更起。","趋庭为尔复缓颊，一杯既空难但已。"]},{"t":"次韵大人待次吴陵邑五首 其一","f":"五言律诗","c":["待次吴陵邑，身修道日章。","兰陔留古郡，花县得邻乡。","未即抟扶上，端嫌代斲伤。","萧閒文墨外，乐趣问濠梁。"]},{"t":"次韵大人待次吴陵邑五首 其二","f":"五言律诗","c":["待次吴陵邑，优哉阅岁年。","凤池疏海角，鶠阁竦城颠。","莳药时分颖，栽花自溉泉。","新篇谈笑就，寄自鲁邦传。"]},{"t":"次韵大人待次吴陵邑五首 其三","f":"五言律诗","c":["待次吴陵邑，行趋宝婺邦。","葱茏连越岫，澄澈泳桐江。","八咏风生座，双林月映窗。","胜游知不晚，官履欲飞双。"]},{"t":"次韵大人待次吴陵邑五首 其四","f":"五言律诗","c":["待次吴陵邑，常安揭小轩。","祗从支遁隐，不问景纯言。","颜巷居多乐，陶庐似少喧。","朝歌屈虞诩，清切未殊恩。"]},{"t":"次韵大人待次吴陵邑五首 其五","f":"五言律诗","c":["待次吴陵邑，鹂黄报早春。","红归花蕾浅，青到柳梢新。","穷约那趋俗，虚缘自葆真。","荣枯多反衍，坐笑党频频。"]},{"t":"和送张元方南京掾","f":"五言律诗","c":["下位沉英俊，青编乐自多。","官曹依绿水，词笔注黄河。","初日嗟贪鼠，今年未饮鹅。","陪京资禄养，何计免奔波。"]},{"t":"题横林馆","f":"五言律诗","c":["治剧知非称，投閒得退栖。","聊从诗酒污，顿免簿书迷。","幻界荣枯小，真乘宠辱齐。","横林孤馆静，辰发踏荒鸡。"]},{"t":"题须江驿","f":"五言律诗","c":["寓馆飘风雨，高文耀日星。","閒身关历览，左宦在零丁。","不见雌雄行，空存长短亭。","襄阳知渐近，岘首映寒坰。"]},{"t":"次韵李子京宋城道中诗三首 其一","f":"五言律诗","c":["沙冈牛酒市，渺岸指前程。","断梗随鸥远，残霞与鹜平。","村声喧坱莽，林影倒澄瀛。","俗物难遮眼，支离病骨轻。"]},{"t":"次韵李子京宋城道中诗三首 其二","f":"五言律诗","c":["通涂了无畏，清世足章程。","击壤民风乐，持衡国势平。","米盐丰道路，桴鼓静寰瀛。","佳气葱葱近，心随过鸟轻。"]},{"t":"次韵李子京宋城道中诗三首 其三","f":"五言律诗","c":["积累三冬学，淹通万古程。","孤高吴子札，该洽蜀君平。","曹事今司李，官封近接瀛。","公侯阶有渐，五斗未容轻。"]},{"t":"寄题海会晚实轩","f":"五言律诗","c":["素节清霜重，金苞照座隅。","根深容四老，品贵入三都。","骚客真宜友，侯封未易奴。","旧时书两庙，感事涕沾濡。"]},{"t":"登搀云亭和工部兄韵","f":"五言律诗","c":["危亭耸山巅，萦纡一径穿。","林深将蔽日，涛怒欲浮天。","江北迷堤树，淮南起饷烟。","结庵容寄傲，从此息攀缘。"]},{"t":"次韵和庆善游圆觉寺归四首时仆亦方自径山归 其一","f":"五言律诗","c":["青鞋访云水，僧馔饫茭蒲。","落拓人谁识，迂愚世所无。","鴳鹏从物化，牛马任人呼。","世事何须问，诸公在禁途。"]},{"t":"次韵和庆善游圆觉寺归四首时仆亦方自径山归 其二","f":"五言律诗","c":["步屧寻幽子，谈玄孰造微。","离群虽念独，选胜遂忘归。","世路从争席，年华逼授衣。","平生付双琐，手抚送鸿飞。"]},{"t":"次韵和庆善游圆觉寺归四首时仆亦方自径山归 其三","f":"五言律诗","c":["招提行问道，末学倦编蒲。","不际方为际，应无令尽无。","归来聊自赋，隐去谢人呼。","宦路分夷险，平生谁识途。"]},{"t":"次韵和庆善游圆觉寺归四首时仆亦方自径山归 其四","f":"五言律诗","c":["黄花兼露重，白鸟带烟微。","云伴渊明出，风随曾点归。","经丘携芰制，视膳辍兰衣。","景物供清兴，诗高直欲飞。"]},{"t":"夜归不寐","f":"五言律诗","c":["流莺惊节物，乐事二毛前。","山简不堪醉，渊明方欲眠。","谈馀愁似茧，坐久腹如蝉。","日出重游衍，残花有杜鹃。"]},{"t":"次韵庆善九日","f":"五言律诗","c":["二九依辰至，追欢付曲生。","竹根拚醉卧，菊蕊正牵情。","杜曲酬佳节，陶翁爱此名。","吹花更吹帽，相值得豪英。"]},{"t":"庆善再和复和","f":"五言律诗","c":["异县逢佳节，羁愁太瘦生。","黄花真解事，白首缓伤情。","十日尚堪醉，一杯犹有名。","眼前多胜士，何必洛中英。"]},{"t":"幽居二首 其一","f":"五言律诗","c":["幽居无俗韵，胜事特关心。","研度疲三豕，床敷戏一禽。","覆舟棋自戒，中圣酒时斟。","萧洒侯来访，窗前绿透林。"]},{"t":"幽居二首 其二","f":"五言律诗","c":["名胜音尘隔，怀贤自渴饥。","千岩耸秀处，一榻独悬时。","盛夏衣裳懒，深林枕簟宜。","招邀何以待，数卷谪仙诗。"]},{"t":"即事二首 其一","f":"五言律诗","c":["四月麦已熟，清寒久不禁。","林深来蜀魄，屋破绝燕禽。","幽屏儿仍出，贫居病更侵。","萧然北窗下，趺坐独求心。"]},{"t":"即事二首 其二","f":"五言律诗","c":["巷转柔桑陌，门依绿柳桥。","因人嫌碌碌，拔俗自超超。","嫩碧半篙涨，残红一眼飘。","卑栖有微分，斥鴳得逍遥。"]},{"t":"试墨","f":"五言律诗","c":["为适閒中趣，晴窗试墨卿。","磨研轻有晕，条畅细无声。","紫玉浮云净，寒烟点漆明。","鸟鸣春昼寂，一笑万缘轻。"]},{"t":"微雨小饮客至阍人辞以出令追路已不及偶作","f":"五言律诗","c":["昨日持三白，今朝解八支。","聊为犀首饮，尽笑虎头痴。","冠履从来懒，杯铛且自持。","是中多乐趣，勿遣外人知。"]},{"t":"题庵壁","f":"五言律诗","c":["葛翁携葛姓，小愒葛桥边。","葛泉出萝葛，一派自潺湲。","咫尺葛山观，金丹问葛仙。","耳孙忝瓜葛，行隐葛山巅。"]},{"t":"龙井","f":"五言律诗","c":["古甃泓澄浅，涓涓似有源。","蒸云骤游宇，吹雨忽翻盆。","泉伏微如蠋，泥蟠肆任蚖。","崭然头角见，坐禠叶公魂。"]},{"t":"龙堂","f":"五言律诗","c":["一室飞山腹，蜿蜒像设精。","班传五色贵，食辨百花名。","睡颔应难探，云鳞讵可婴。","从祈得甘泽，栖壁有碑铭。"]},{"t":"观山谒蒋叔明赵邻叔二坟","f":"五言律诗","c":["寒食观山道，佳城隔垄分。","赵公今不武，蒋老去修文。","歌薤犹前日，栽松已插云。","生平各投分，絮酒荐蒿焄。"]},{"t":"昭怀皇后挽歌词二首 其一","f":"五言律诗","c":["天作元符合，哀荣极始终。","陵陪永泰近，礼视孝章隆。","匰主跻新庙，廞衣贲下宫。","柏城连献悯，萧瑟夜台风。"]},{"t":"昭怀皇后挽歌词二首 其二","f":"五言律诗","c":["寂寞崇恩殿，飙轮去弗还。","尊名千古外，显册两朝间。","座冷金釭暖，香消玉釜閒。","神游返姑射，脱屣谢尘寰。"]},{"t":"李楚老尚书挽歌词三首 其一","f":"五言律诗","c":["席宠三台后，疏恩八座荣。","朝廷真大蔡，边鄙更长城。","戾社符刀梦，王墀识履声。","阴功归壤子，衮衮出名卿。"]},{"t":"李楚老尚书挽歌词三首 其二","f":"五言律诗","c":["东里推人杰，西清列从班。","裤襦康二蜀，裘带靖三关。","赤白囊无警，朱丹毂遂还。","登龙门旧贵，奕叶道家山。"]},{"t":"李楚老尚书挽歌词三首 其三","f":"五言律诗","c":["得谢恩重起，追荣爵更崇。","龙蛇新岁忌，鹓鹭旧行空。","图象人怀惠，尊名帝念功。","遭时淹陈寔，大耋偶相同。"]},{"t":"方待制挽词二首 其一","f":"五言律诗","c":["琐闼枢机地，储闱羽翼人。","蕝仪容典备，校历闰馀亲。","云路箕乘说，泉台岳返申。","荀龙行济美，交旧独伤神。"]},{"t":"方待制挽词二首 其二","f":"五言律诗","c":["佳城酾酒奠，长夜殒星知。","今代儒林传，诸方德政碑。","朝廷躬蹇蹇，丘壑自怡怡。","安得研几士，推穷妙万蓍。"]},{"t":"莫子宪中奉挽歌词三首 其一","f":"五言律诗","c":["嗜学唯何甚，飞声实久如。","郎星频省户，卿月转周庐。","桂奠房祠酒，芸残册府书。","音容千古外，坟槚閟南徐。"]},{"t":"莫子宪中奉挽歌词三首 其二","f":"五言律诗","c":["材资合黄阁，器业偃朱轓。","教府依模范，枢庭验讨论。","成梁繄杜预，障水幸王尊。","二纪朋僚旧，追怀恸寝门。"]},{"t":"莫子宪中奉挽歌词三首 其三","f":"五言律诗","c":["令子承家学，诸儒拥后尘。","无双问江夏，第一擢平津。","宣谕传黄甲，褒称对紫宸。","公师有追贲，行庆密章新。"]},{"t":"致政朝奉亲家丁公挽歌词二首 其一","f":"五言律诗","c":["节概松千丈，声华桂一枝。","牵丝始游宦，解组遽安时。","人美抛官早，身嫌了事迟。","反真聊示病，曾不谒巫医。"]},{"t":"致政朝奉亲家丁公挽歌词二首 其二","f":"五言律诗","c":["贯籍明光殿，颐神通德门。","庆源来化鹤，高隐谢惊猿。","冕绂承前范，箕裘付后昆。","论婚情义重，祖载独伤魂。"]},{"t":"胡诚甫朝散挽歌辞","f":"五言律诗","c":["学擅敷门邃，年跻赐几尊。","降崧钟秀气，游岱返英魂。","宰树黄岩拱，房祠赤绂昏。","密章行胙国，有子大公门。"]},{"t":"凌丞事挽词二首 其一","f":"五言律诗","c":["铨材今秀孝，较德古沉冥。","已悟桃花理，犹翻贝叶经。","妙观存述造，阴德有平停。","今夜稽山道，天沉处士星。"]},{"t":"凌丞事挽词二首 其二","f":"五言律诗","c":["紫诰恩华重，青纶命服荣。","无香然玉釜，有子胜金籯。","禅解超尊宿，乡评服老成。","棘人深孺慕，捧土作佳城。"]},{"t":"许处士挽词二首 其一","f":"五言律诗","c":["场籍声华茂，家庭志意修。","光阴归翰墨，器业谩林丘。","学府空鸡蹠，贤书误鹤头。","门基多克荷，衮衮出公侯。"]},{"t":"许处士挽词二首 其二","f":"五言律诗","c":["濉阳忠烈后，泊水老成人。","庠校推模表，州闾训睦姻。","决疑辞郭璞，营急似陈遵。","碑字深无愧，銮坡得从臣。"]},{"t":"鲁国太夫人杨氏挽歌词四首 其一","f":"五言律诗","c":["教子青云上，持身白业中。","挟医来相第，赐襚出宸衷。","鸾诰前恩在，鱼轩旧辙空。","东方妙喜国，断取作幽宫。"]},{"t":"鲁国太夫人杨氏挽歌词四首 其二","f":"五言律诗","c":["未肖甘泉像，先疏曲阜封。","春秋绵六纪，甘毳极千钟。","远日朝廷趣，容车郡国供。","吴人交恻楚，相杵夜停舂。"]},{"t":"鲁国太夫人杨氏挽歌词四首 其三","f":"五言律诗","c":["鳣堂推胄贵，蝉冕媲夫荣。","玉釜香无验，金辉馆已迎。","鹊梁占胙土，龟墨报佳城。","今代谁词伯，刊碑远德声。"]},{"t":"鲁国太夫人杨氏挽歌词四首 其四","f":"五言律诗","c":["子贵今台辅，才高古荩臣。","与民开寿域，为国斡洪钧。","会友伤陶发，迎师忆孟邻。","栾栾亲负土，肠断冢边麟。"]},{"t":"学正郭勉夫示诗次韵答之","f":"五言古诗","c":["有道家声远，沉机足干时。","松生非培塿，檀伐待沦漪。","虎脊卑凡乘，蛾眉疾众姬。","一鸣惊伍举，千里器王圭。","德令温温著，名香蔼蔼驰。","披庄问同异，执礼判嫌疑。","操尚倾涓子，才华进客儿。","适齐非鼓瑟，逃楚笑吹篪。","艺苑高三绝，书庠肃五仪。","涌泉推敏思，翻水播英辞。","计吏趋兰省，诸生偃璧池。","行殊师也过，论鄙释之卑。","默识扳安世，多方劣惠施。","风标寒似玉，机警利如锥。","高翥千龄鹤，前知五总龟。","碎金珍谢傅，馀锦梦丘迟。","谬学邯郸步，工施浑沌眉。","文科将赫奕，荣路即威夷。","器业今为重，功勋士所期。","他年青竹上，凛凛看名垂。"]},{"t":"勉夫示诗鸣其穷甚哀因次韵答之极其贫悴之态而卒勉之以科举庶广其意也","f":"五言古诗","c":["落落超馀子，干时命未当。","摧伤窘文阵，拓落尚书庠。","賨货无山积，毛群欠谷量。","蜗庐寒不展，龙具夜何长。","牍谩三千富，年侵四十彊。","有车乘下泽，无梦入高唐。","藜糗甘珍荐，桑枢自峻堂。","书佣跧净院，舂赁寄修廊。","异鬼时相笑，邻家许借光。","低佪涸辙鲋，进退触藩羊。","原宪贫非病，荣期乐处常。","财雄劣程郑，赀钜笑秦杨。","甫里田多潦，浔阳径就荒。","白驹嗟逸豫，黄鸟怨遗忘。","薪乏支离束，钱空赵壹囊。","晨餐烦乞米，夜读待然糠。","词艺闻精敏，名声已激扬。","登荣将赫奕，处困暂徊徨。","志气宜轩翥，文辞忌怨伤。","逐贫高赋就，丰廪换龟肠。"]},{"t":"中秋和韵","f":"五言古诗","c":["凉夜清商半，层空素月初。","腾清来洞户，委照入空庐。","银海亭亭上，金波煜煜舒。","纤阿今夕御，少昊昔年墟。","魄射澄澜倒，光涵脱叶疏。","阶蓂生乍足，庭桂落堪锄。","东鄙人摛藻，西园客燕胥。","未高尤潋滟，当午更踟躇。","气挟金飙爽，光从玉宇摅。","鉴圆疑傍架，轮正若依舆。","影挂千林上，明同万里馀。","云开无点缀，火退觉虚徐。","滉漾吞星彩，晶荧溯日车。","惊枝翻异鹊，减脑谢游鱼。","田净琼初种，窗明雪未除。","胡床情恋嫪，小舫兴勤渠。","珠盛辉兹水，潮高壮尾闾。","倾寒涤肝胃，扬彩媚衣裾。","郡古休敲榜，官閒置简书。","万家兴釂鼓，恺乐旐维旟。"]},{"t":"次韵逢叔喜雪","f":"五言古诗","c":["始见穿帘隙，俄惊照屋山。","春容先苑树，夜色误城关。","砧积疑铺练，盆消若盗环。","酒醇怀泛蚁，诗敏过求鹇。","滉漾迷珠泽，便娟掩玉颜。","人饥毡共咽，马冻荐难悭。","势急因空乱，形移任地班。","舞深争巧黠，啭细弄幽閒。","淮右提师入，山阴访友还。","江湖禽影断，弦木未须弯。"]},{"t":"次韵李倅安上喜雪","f":"五言古诗","c":["兔苑佳宾集，龙山上瑞臻。","微飘方自弄，乱洒忽无垠。","剪水层空堕，装春病蘖新。","缤翻投隙巧，历乱点衣匀。","急每随风阵，高将拥日轮。","阶閒铺六出，檐重压千钧。","片落梅初谢，毬飘柳未颦。","赏清疑不夜，惊晚误司晨。","朔漠寒沙起，湘吴美酎陈。","地荒包委琐，木朽盖轮囷。","舴艋寻幽客，蜗牛卧冷人。","稍晴芳意动，散策共寻春。"]},{"t":"再和","f":"五言古诗","c":["皑皑盈尺瑞，及此腊前臻。","滉漾连三暮，萦盈遍九垠。","青腰阴巧露，白帝羽仪新。","坤轴埋藏厚，天潢泻落匀。","瑶林变园榭，缟带逐车轮。","膏润归农亩，雕裁自化钧。","吟寒诗胆健，装冷妩眉颦。","点袖朝正日，侵靴立仗晨。","境同秋月净，句鄙散盐陈。","白玉藏千室，黄云卜万囷。","江皋迷宓女，姑射想神人。","早晚晴光动，郊原探早春。"]},{"t":"十二月初四日游吴山院","f":"五言古诗","c":["稳坐踰年矣，浑消髀肉顽。","两儿挟篮舆，十里访吴山。","佛老聊施佞，官曹未畏瘝。","烟林穿窈窈，岩溜揭潺潺。","楼观修篁外，招提翠麓间。","嶝危愁惫力，潭净怯衰颜。","身缚何因脱，心纷得暂删。","岁穷嗟俛仰，境胜彊跻攀。","腊出因休吏，晡归及闭关。","相将投此帻，永伴黑衣閒。"]},{"t":"走笔追记十二月九日潭头之游","f":"五言古诗","c":["三益得岂易，一游营亦难。","地偏如避俗，春早自排寒。","霖潦逢初霁，年华念欲单。","支筇卜遐眺，挈榼展清欢。","茶坞千家密，梅林十里宽。","幽寻穷窈窕，危陟遍巑岏。","有地堪肥遁，幽人卜考槃。","后前罗峻岭，左右绕惊澜。","西望双藤老，南瞻巨石盘。","千章丛古木，九畹秀崇兰。","手板看苍翠，军持上激湍。","醉乡因蚁酎，水厄为龙团。","晚景云低树，归途雨压冠。","明惊烽火逼，小艇起前滩。"]},{"t":"十二月二十三日立春中散兄棣华第六会特盛是日天大雪小孙女出綵幡胜及花柳精巧夜漏且五鼓方罢既归不得寐偶成律诗纪事拜呈中散兄兼简公任阜民详定侍郎道祖签幕判院朝提辖奉议卿任宝录待制","f":"五言古诗","c":["异县逢春启，羁怀百不堪。","频倾次道酿，聊喜阿云谈。","棣萼仍清集，辛盘助半酣。","綵幡惊节物，玉屑瑞田蚕。","太簇律初应，德星堂不惭。","共誇筵秩秩，那羡府潭潭。","济美三公后，逃禅二老参。","清欢时择胜，冲操自廉贪。","丹荔来闽部，黄鱼出峤南。","云泉烹赐茗，罗帕荐珍柑。","经醉香浮座，言归钟动庵。","萧然文字饮，共赋鹿鸣三。"]},{"t":"六月六日大暑市中无肉庖厨索然作六言三首 其一","f":"词","c":["翠竹碧梧入望，紫茄白苋供槃。","未办楚王鸡蹠，难求闵叔猪肝。"]},{"t":"六月六日大暑市中无肉庖厨索然作六言三首 其二","f":"词","c":["常馔素谙苜蓿，忍饥何必槟榔。","自叹獐头鼠目，难辞蝉腹龟肠。"]},{"t":"六月六日大暑市中无肉庖厨索然作六言三首 其三","f":"词","c":["三白旧甘蔬食，八关聊复斋支。","蚁酒似闻将熟，蟹螯应得重持。"]},{"t":"再和三首 其一","f":"词","c":["晨飧仅有醢豆，夜饮应无烛槃。","属餍何取鸡肋，委顺甘为鼠肝。"]},{"t":"再和三首 其二","f":"词","c":["野步自锄芦菔，轻尘试煮桄榔。","坐喜青刍入眼，不须紫笋搜肠。"]},{"t":"再和三首 其三","f":"词","c":["腊毒虽无后悔，转雷已觉难支。","异馔那施方丈，寒泉且饮军持。"]},{"t":"二陈作书怀诗亦次韵","f":"七言律诗","c":["山城真称著寒儒，绕屋青苍似故居。","吏牍纠纷惭磔鼠，斋厨萧索待泔鱼。","懒如园令将移病，穷似虞卿合著书。","赖是丰年民气乐，梦回时见旐维旟。"]},{"t":"圄空讼息复遇肆眚庭事萧然蒙良器解元宠诗辄以二章为谢 其一","f":"七言律诗","c":["一官铜墨付疏顽，岁好人和偶未瘝。","东亩黄云穈芑卧，北扉青草纆徽閒。","鹄亭夜觉冤氛静，蝇笔晨惊霈泽颁。","倪耄欢谣归帝力，风人溢美但赪颜。"]},{"t":"圄空讼息复遇肆眚庭事萧然蒙良器解元宠诗辄以二章为谢 其二","f":"七言律诗","c":["编户相安易得情，年来狴犴每刑清。","庭閒不复施梧象，俗朴聊同示草缨。","牍背仅能平枉桡，需头那复觊褒荣。","人言官事无由了，暂得居官事了名。"]},{"t":"次德林新亭诗韵","f":"七言律诗","c":["缿讼无多得暂閒，结亭聊就碧鲜间。","胡床寄目中宵月，手板支颐四面山。","楂带水禽流浅濑，帆随烟艇转前湾。","登临似与尘寰隔，况复朋从接笋班。"]},{"t":"次韵子充九日建天宁道场罢遂游尧祠","f":"七言律诗","c":["悒悒无聊坐学宫，衔杯阻共玉西东。","祝延精舍臣心重，择胜丛祠友好隆。","休叹青衫淹小县，且从乌帽落商风。","喜君句法无糕字，始信才华梦得同。"]},{"t":"次韵德升游尧庙","f":"七言律诗","c":["颓垣老屋寄荒村，八彩修眉俨若存。","古砌荒凉无历草，奠觞牢落想衢樽。","云山绕郭清如活，烟艇摇波渺欲翻。","循牒归来同胜赏，免烦诸友为招魂。"]},{"t":"九日汝明留郡中不遂同游以诗见寄次韵","f":"七言律诗","c":["三年卜筑慕幽人，九日无欢愧病身。","始谓窥临陪胜友，那知岑寂度萧辰。","醪敷卷白欣初熟，菊蕊舒黄正斩新。","闻道小蛮新教舞，归时呼客莫辞频。"]},{"t":"题观音院","f":"七言律诗","c":["弱水无风到海山，慈容亲觐紫旃檀。","亭亭宝刹凌云近，湛湛清池漱玉寒。","橘熟独垂红万颗，竹迷曾莳碧千竿。","热官步武何容到，散秩须知第一官。"]},{"t":"诸生绝粮偶作二首示勉夫 其一","f":"七言律诗","c":["庖厨落寞不堪闻，弹铗无鱼甑有尘。","谁识箪瓢颜氏乐，可怜鲑菜庾郎贫。","固穷始合称君子，临难聊须语细人。","曳褷长歌商颂在，未应怼憾去来频。"]},{"t":"诸生绝粮偶作二首示勉夫 其二","f":"七言律诗","c":["饥肠愁坐耳无闻，放饭先疑甑拾尘。","闻说食功非食志，政宜忧道不忧贫。","佐饔但有思尝者，执爨初无欲凊人。","好向计台勤自列，文移见却已频频。"]},{"t":"次韵刘卿任阜民对假菊花尝新酒","f":"七言律诗","c":["隆冬急雪舞淄渑，那得鲜鲜细菊呈。","何处幻师来衒巧，此花词客最钟情。","盈尊更值醪敷热，下箸仍欣鲙缕赪。","应笑蓬蒿张仲蔚，忍寒独坐到黎明。"]},{"t":"次韵德升见怀","f":"七言律诗","c":["米廪无喧似结庐，一檐寒竹伴幽虚。","閒开桑落倾浮蚁，净展芸签拂蠹鱼。","频枉诗筒从我读，已留斋壁待君书。","二千石子人中爽，风月高情更起予。"]},{"t":"次韵德升再讲酬唱","f":"七言律诗","c":["莲社追攀每愧心，诗盟此假偶重寻。","孤高旧压元和体，清警新闻正始音。","龟洛赋成应夺锦，鸡林价重定酬金。","自怜潦倒无佳制，东望家山但越吟。"]},{"t":"次韵蔡安度秀才赋盐","f":"七言律诗","c":["法更盐筴利源开，濒海熬波亹亹来。","贡篚烧羊谩南北，嘉笾形虎间榛梅。","锻圭搥璧严疆域，积雪飞霜阜货财。","滋味佐饔周九土，柳星端合祀坛垓。"]},{"t":"青州试院次监门韵四首呈同事李无咎补之签判王柏立之刘及至父二宰郑与权存道司户李致志道县丞 其一","f":"七言律诗","c":["朱颜幕府美如英，庇邑优闲闭讼庭。","语掾气刚工论事，讲郎材拙只横经。","相从此地初披雾，却望遥天想聚星。","速发试题乘不备，母令掩耳及惊霆。"]},{"t":"青州试院次监门韵四首呈同事李无咎补之签判王柏立之刘及至父二宰郑与权存道司户李致志道县丞 其二","f":"七言律诗","c":["东秦人士富豪英，乡老宾贤上帝庭。","玉笋未知谁得地，金籯闻说剩通经。","雄夸气各千云汉，妙制文多焕斗星。","水镜诸公标鉴在，大声从此起非霆。"]},{"t":"青州试院次监门韵四首呈同事李无咎补之签判王柏立之刘及至父二宰郑与权存道司户李致志道县丞 其三","f":"七言律诗","c":["樽酒重阳泛菊英，此时应得到家庭。","奔趋试席虽深贯，囚锁文闱苦未经。","梦入故园时栩栩，愁侵衰鬓欲星星。","评文赖有金闺彦，敏手从来号震霆。"]},{"t":"青州试院次监门韵四首呈同事李无咎补之签判王柏立之刘及至父二宰郑与权存道司户李致志道县丞 其四","f":"七言律诗","c":["前山云物望英英，拘窘无从出户庭。","盖众未知除患术，居閒聊喜卫生经。","客涂淫滞将弥月，王事勤劳每戴星。","已恨归期误占鹊，阿香何苦更飞霆。"]},{"t":"再次韵四首呈至父 其一","f":"七言律诗","c":["茂宰才名莫与京，久宜迁擢润朝廷。","儒林传记夸三箧，圣域淹通贯十经。","豪县暂颁天子诏，清资已应议郎星。","危言峻节他年事，肯向威颜慑震霆。"]},{"t":"再次韵四首呈至父 其二","f":"七言律诗","c":["棘绕重门昼亦扃，白袍摇笔坐中庭。","摛词绵密多根道，论事轩昂各传经。","学博素推通德里，名高先动进贤星。","知谁吉梦如扬辇，一石龙驹落大霆。"]},{"t":"再次韵四首呈至父 其三","f":"七言律诗","c":["文卷纵横未易名，欲搜佳笔送王庭。","去留彼我心无著，工拙锱铢眼尽经。","老信虚名真画饼，忙知急景甚飞星。","自怜考阅专精甚，不觉猝然柱破霆。"]},{"t":"再次韵四首呈至父 其四","f":"七言律诗","c":["披卷疲劳亦暂停，相携款睇聚閒庭。","绘图细阅吴生品，茗盌分评陆子经。","榜帖未应凭主第，文穷端已送奴星。","毬场絷锁惊踰月，可信流光甚疾霆。"]},{"t":"出院有期呈同院二首 其一","f":"七言律诗","c":["门前舆马已纷纷，犹尔痴迷校艺文。","山色未容飞盖赏，市声时得隔墙闻。","裴头黄尾皆前定，王后卢前谩自分。","颇忆安居卧斋榻，净看香雾起微焚。"]},{"t":"出院有期呈同院二首 其二","f":"七言律诗","c":["旅怀牢落倦文玚，宪网拘挛出处妨。","眼力半消嫌夜烛，腰围顿减怯秋霜。","到家会是扬三喜，取第谁同郭八郎。","趣驾莫孤糕酒会，东篱菊蕊已金黄。"]},{"t":"次韵祝守康鹿鸣宴赠诸先辈 其一","f":"词","c":["清香画戟，戟燕儒流，场籍英材喜博收。","奋袖谈辞争落落，抠衣矩步更秋秋。","新篇奖激华如衮，公议归怀缀若旒。","蕊榜登荣即从政，定知果艺过由求。"]},{"t":"次韵祝守康鹿鸣宴赠诸先辈 其二","f":"七言律诗","c":["观光六十富豪英，宾送春闱属钜卿。","乐采旧知多藻茆，燕敖今喜食蒿苹。","糊名选艺无私见，置醴优贤有颂声。","成就旋归充贡职，鲁人歆艳始知荣。"]},{"t":"次韵祝邦直题饮凤泉","f":"七言律诗","c":["万里溪源出小池，乔林修竹映清辉。","迁莺榜内偏留落，饮凤泉边习遁肥。","游览忽纡都骑贵，称夸更得綵毫挥。","故山水石那优此，肯为低腰便赋归。"]},{"t":"示友卿","f":"七言律诗","c":["飞藿萧萧晚自零，来时灌木始欣荣。","每因劝学添文思，却为回文动旅情。","好逐诸儒勤释菜，莫忧贫嫂便轑羹。","似闻阚泽中宵梦，月里分明有姓名。"]},{"t":"次韵若拙碧线泉","f":"七言律诗","c":["掉缭穿桥一线过，济南金色漫浮波。","共疑园客春投茧，直恐针神夜过河。","贯脱已遗交甫佩，缕飞如掷幼舆梭。","晚风披拂俄中断，拆袜虽长苦不多。"]},{"t":"诸生诣府见留再任偶作示勉夫二首 其一","f":"七言律诗","c":["鲁堂诗礼号多儒，文席非才误诏除。","贤路久妨颜已厚，儒宫相借计诚疏。","化鹍未敢图飞翼，搏虎谁能复下车。","诣府自言无以称，空衔诸彦意勤渠。"]},{"t":"诸生诣府见留再任偶作示勉夫二首 其二","f":"七言律诗","c":["安閒喜得伴林居，分教无功恨有馀。","闵贡政为投劾计，何蕃空上乞留书。","论文每愧瑕疵汝，廷誉何烦俎豆予。","谁识白云千里念，终更计日望吾庐。"]},{"t":"将至襄陵二首 其一","f":"七言律诗","c":["西风寥栗不须悲，云日轻明政自奇。","远岸绿飘梧槭槭，疏林红露枣离离。","味回新醑愁眉破，凉入单纨病骨知。","试问夜窗灯火读，何知蚊蚋扑缘时。"]},{"t":"将至襄陵二首 其二","f":"七言律诗","c":["千里昆崙一月风，乘流初不恨途穷。","南陔就养晨昏乐，东榻忘怀笑语同。","牛酒故应推汴上，鲈莼那复念吴中。","明朝系缆襄陵驿，试上高原望郁葱。"]},{"t":"君山饭僧荐考妣元述示诗次其韵","f":"七言律诗","c":["负郭檐楹古道场，山形连接楚人黄。","千寻宝刹留幡影，万里沧波对练光。","问膳香兰无复日，沾襟青血自成行。","才收英器还遵路，三昧高僧笑我忙。"]},{"t":"次韵敦仁教授述怀","f":"七言律诗","c":["十载文华盖众英，州庠微禄代躬耕。","半生甘为方穿碍，此假那因曲木惊。","折角谈经于道胜，低簪下匕以身轻。","两朝大典资编削，莫向西风厌宦情。"]},{"t":"近蒙夏蒙夫教授用赠太守韵见贻辄复和答","f":"七言律诗","c":["百家六艺日披吟，问学渊源已造深。","旧直蓬山无俗梦，今官槐市有清阴。","公馀绿绮乘閒抚，客退黄庭每自临。","官冷定知尘满甑，谁人裹饭慰愁霖。"]},{"t":"伏蒙达之学谕以诗宠眷生日次韵酬谢","f":"七言律诗","c":["穷通谁复问东龟，材命由来略可推。","去恶敢言除亩薤，律贪聊慕拔园葵。","百年永悼悬弧日，一顾垂当解印时。","诗句清新褒借甚，却嫌无当玉为卮。"]},{"t":"段去尘教授示书以茶菊自况作诗谢之","f":"七言律诗","c":["高标落落敢评题，托物铨量庶似之。","娱客精神真北苑，可人风味剧东篱。","云腴斗早惊先出，霜蕊禁寒属后期。","便欲相称为二陆，居然桑苧与天随。"]},{"t":"旬休延圣院纳凉周澶州招饮呈德升诗二首 其一","f":"七言律诗","c":["年来形迹苦西东，邂逅招提一笑同。","世事休论痴黠半，物情都在圣贤中。","地灵蒸郁疑无著，友胜喧嚣自不通。","借与方床宽六尺，道人知有竹间风。"]},{"t":"旬休延圣院纳凉周澶州招饮呈德升诗二首 其二","f":"七言律诗","c":["讲席朝来得暂停，蓝舆同入法王城。","清壶照座三棱瑩，小扇摇风六角轻。","方罫共争棋上劫，顽盆更酌酒中兵。","佳宾更赖王思远，霜气能令暑气清。"]},{"t":"元巳日王循德招饮方池宏道兄有诗奉和以纪一时之事","f":"七言律诗","c":["浮爽清波正日迟，出郊修禊属芳时。","幸陪飞观朋簪盍，未睹华堂舞袖僛。","命中已于三耦见，争雄仍向一枰知。","爱君多艺能倾坐，岂但流觞记逸诗。"]}]};